INSERT INTO NPC (npcID, name, biography, contribution, asset) VALUES
(121, 'Wartawan Muda', 'Wartawan muda yang merakam siaran khas tentang Perdana Menteri Malaysia (watak rekaan).', 'Menemu bual tokoh dan melaporkan sejarah kepimpinan negara kepada rakyat.', 'jejaka_melayu.png'),
(122, 'Guru Sejarah', 'Guru Sejarah yang buku teksnya tiba-tiba menghidupkan para Perdana Menteri (watak rekaan).', 'Menjadikan pelajaran tentang pemimpin negara mudah difahami oleh murid.', 'perempuan_melayu.png'),
(123, 'Murid Penyelidik', 'Murid yang membuat album kad koleksi Perdana Menteri untuk projek sekolah (watak rekaan).', 'Mengumpul maklumat tentang pemimpin negara untuk dikongsi bersama rakan.', 'budak_gajet.png'),
(124, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Malaysia.', 'Memperjuangkan kemerdekaan secara rundingan dan merealisasikan Pembentukan Malaysia pada 16 September 1963.', 'tunku_abdul_rahman.png'),
(125, 'Tun Abdul Razak bin Hussein', 'Perdana Menteri kedua Malaysia.', 'Mengembalikan keamanan selepas peristiwa 13 Mei 1969 menerusi MAGERAN dan memperkenalkan Dasar Ekonomi Baru.', 'tun_abdul_razak.png'),
(126, 'Tun Hussein bin Onn', 'Perdana Menteri ketiga Malaysia.', 'Memperkenalkan Amanah Saham Nasional Berhad dan Program Rukun Tetangga.', 'tun_hussein_onn.png'),
(127, 'Tun Dr. Mahathir bin Mohamad', 'Perdana Menteri keempat dan ketujuh Malaysia.', 'Wawasan 2020, pembinaan Putrajaya, KLIA, Menara Berkembar Petronas (KLCC) dan penubuhan HICOM.', 'tun_dr_mahathir.png'),
(128, 'Tun Abdullah bin Ahmad Badawi', 'Perdana Menteri kelima Malaysia.', 'Memperkenalkan Koridor Wilayah Ekonomi dan Pelan Integriti Nasional (PIN).', 'tun_abdullah.png'),
(129, 'Dato\' Sri Mohd Najib bin Tun Abdul Razak', 'Perdana Menteri keenam Malaysia.', 'Memperkenalkan Gagasan 1Malaysia dan Program Transformasi Kerajaan (GTP).', 'dato_sri_mohd_najib.png'),
(130, 'Tan Sri Muhyiddin bin Md Yassin', 'Perdana Menteri kelapan Malaysia.', 'Menubuhkan Majlis Tindakan Ekonomi (MTE) dan mengumumkan bantuan kewangan serta peruntukan besar semasa PKP pandemik COVID-19.', 'tan_sri_muhyiddin.png'),
(131, 'Dato\' Seri Ismail Sabri bin Yaakob', 'Perdana Menteri kesembilan Malaysia.', 'Memperkenalkan konsep Keluarga Malaysia yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 'dato_seri_ismail_sabri.png'),
(132, 'Yang di-Pertuan Agong', 'Ketua Utama Negara yang melantik Perdana Menteri secara rasmi.', 'Melantik Perdana Menteri dan menerima nasihatnya, termasuk dalam Mesyuarat Majlis Raja-Raja.', 'raja.png')
INSERT INTO Narrative (narrativeID, narrativeTitle, eraID, summary) VALUES
(701, 'Siaran Khas dari Pejabat Perdana Menteri', 7, 'Masuki peranan wartawan muda yang menemu bual Yang di-Pertuan Agong dan Perdana Menteri yang awal. Kau mengenali jawatan Perdana Menteri, biodata dan pencapaian Tunku, Tun Razak dan Tun Hussein.'),
(702, 'Perdana Menteri Keluar dari Buku Teks', 7, 'Masuki peranan guru Sejarah yang buku teksnya tiba-tiba menghidupkan para Perdana Menteri. Kau mengenali tugas Perdana Menteri serta biodata dan pencapaian Tun Dr. Mahathir hingga Dato'' Seri Ismail Sabri.'),
(703, 'Album Kad Koleksi Perdana Menteri', 7, 'Masuki peranan murid penyelidik yang membuat album kad koleksi Perdana Menteri. Kau mengumpul maklumat tentang jawatan, urutan, pencapaian, ciri kepimpinan berwibawa dan cara menghargai pemimpin.');
INSERT INTO Scene (sceneID, sceneStoryline, sceneOrder, narrativeID, asset) VALUES
('e7_n1_s1', 'Pejabat Perdana Menteri di Putrajaya. Skrip siaran masih kosong. Yang di-Pertuan Agong menunggu soalan pertama, tetapi bahan latar menyatakan Perdana Menteri dilantik oleh pihak yang lain.', 1, 701, 'bangunan_perlembagaan.png'),
('e7_n1_s2', 'Bilik arkib stesen penyiaran. Empat pita rakaman pemimpin berselerak dan label tarikh luntur. Penerbit mahu urutan Perdana Menteri yang betul sebelum siaran ke udara.', 2, 701, 'bilik_mesyuarat_formal.png'),
('e7_n1_s3', 'Rakaman lama Stadium Merdeka pada 31 Ogos 1957. Penerbit mahu empat bukti dalam rakaman bahawa Tunku memperjuangkan kemerdekaan secara rundingan, bukan peperangan.', 3, 701, 'laungan_di_stadium_merdeka.png'),
('e7_n1_s4', 'Bilik temu bual. Tunku menjawab soalan tentang latar hidupnya. Penerbit mahu empat butir biodata dipadankan dengan betul sebelum disiarkan.', 4, 701, 'bilik_mesyuarat.png'),
('e7_n1_s5', 'Bilik penyiar menayangkan rakaman peristiwa 13 Mei 1969. Penerbit tersalah menulis bahawa Tun Razak memulihkan keamanan dengan menutup semua pejabat kerajaan. Kau perlu menyemak pencapaiannya.', 5, 701, 'peristiwa_13mei1969.png'),
('e7_n1_s6', 'Taman peringatan di Pulau Keladi, Pekan. Replika rumah kelahiran Tun Razak berdiri di tepi sungai. Penerbit mahu empat butir biodata Tun Razak dipadankan dengan betul.', 6, 701, 'wilayah_persekutuan.png'),
('e7_n1_s7', 'Studio kedua. Penerbit meletakkan kad Tun Hussein Onn di sebelah kad Tun Razak. Penonton muda bertanya mengapa Tun Hussein digelar Bapa Perpaduan.', 7, 701, 'bilik_mesyuarat_modern.png'),
('e7_n1_s8', 'Papan gelaran di dinding studio. Penerbit meminta kau menyiapkan ringkasan gelaran lima pemimpin dengan sumbangan mereka sebelum siaran terakhir.', 8, 701, 'bilik_mesyuarat_dunia.png'),
('e7_n2_s1', 'Bilik darjah Tahun 6. Gambar-gambar dari buku teks terlepas ke papan putih. Murid bertanya apakah tugas sebenar Perdana Menteri dan gambar mana yang menunjukkan setiap tugas.', 1, 702, 'bilik_mesyuarat_modern.png'),
('e7_n2_s2', 'Papan putih sekali lagi. Murid menyenaraikan tugas lain Perdana Menteri yang berkaitan Yang di-Pertuan Agong dan Jemaah Menteri. Ada kad yang tersalah letak.', 2, 702, 'bilik_mesyuarat_formal.png'),
('e7_n2_s3', 'Tun Dr. Mahathir keluar dari halaman buku. Murid menunjuk kad biodata beliau dan meminta kau memadankan dengan betul sebelum loceng berbunyi.', 3, 702, 'bilik_mesyuarat.png'),
('e7_n2_s4', 'Tayangan slaid pencapaian zaman Tun Dr. Mahathir. Murid mahu empat bukti bahawa Malaysia mahu menjadi negara maju melalui Wawasan 2020.', 4, 702, 'pencapaian_ekonomi_perhubungan_dan_perdagangan.png'),
('e7_n2_s5', 'Tun Dr. Mahathir kembali sebagai Perdana Menteri kali kedua. Murid keliru tentang tempoh dan wawasan baharu beliau. Kad nota bertaburan.', 5, 702, 'bilik_mesyuarat_formal.png'),
('e7_n2_s6', 'Giliran Tun Abdullah Ahmad Badawi. Murid memegang kad biodata beliau dan bertanya mengapa beliau digelar Bapa Pembangunan Modal Insan.', 6, 702, 'wilayah_persekutuan.png'),
('e7_n2_s7', 'Papan putih menyenaraikan dua rancangan di bawah Tun Abdullah. Murid keliru antara Koridor Wilayah Ekonomi dengan Pelan Integriti Nasional. Cikgu menulis nota ringkas.', 7, 702, 'bilik_strategi_keselamatan.png'),
('e7_n2_s8', 'Tamat tayangan slaid. Dato'' Sri Najib muncul bersama logo 1Malaysia. Murid bertanya mengapa moto itu mengutamakan rakyat dan apa kaitannya dengan GTP.', 8, 702, 'bilik_mesyuarat_dunia.png'),
('e7_n2_s9', 'Kad terakhir. Muhyiddin dan Dato'' Seri Ismail Sabri muncul. Murid mahu membandingkan sumbangan dua pemimpin yang tampil dalam suasana pandemik.', 9, 702, 'bilik_mesyuarat.png'),
('e7_n3_s1', 'Halaman pertama album, iaitu gambar Bendahara Kesultanan Melayu Melaka di sebelah gambar Perdana Menteri. Cikgu bertanya apa kaitan kedua-dua jawatan itu. Murid keliru.', 1, 703, 'bilik_mesyuarat.png'),
('e7_n3_s2', 'Halaman kedua album hanya ada ruang kosong untuk lima Perdana Menteri terkini. Murid perlu menyusun mereka mengikut tarikh mula memegang jawatan.', 2, 703, 'bilik_mesyuarat_formal.png'),
('e7_n3_s3', 'Halaman ketiga, iaitu Tunku di meja rundingan pembentukan Malaysia. Murid mahu menulis kenyataan tentang pencapaian Tunku pada 16 September 1963.', 3, 703, 'perancangan_pembentukan_malaysia.png'),
('e7_n3_s4', 'Halaman keempat memaparkan sembilan kad kosong. Murid perlu memadankan enam pemimpin dengan pencapaian utama mereka untuk melengkapkan satu jadual.', 4, 703, 'bangunan_perlembagaan.png'),
('e7_n3_s5', 'Halaman kelima, iaitu gambar bilik mesyuarat kerajaan. Murid diminta menulis mengapa pemimpin yang berwibawa penting. Beberapa jawapan di dinding bercanggah.', 5, 703, 'bilik_strategi_keselamatan.png'),
('e7_n3_s6', 'Halaman keenam. Murid ditugaskan menulis cara menunjukkan penghargaan kepada Perdana Menteri. Ada kad yang menyebut cara menghina pemimpin, dan kau perlu memilih cara yang betul.', 6, 703, 'wilayah_persekutuan.png'),
('e7_n3_s7', 'Halaman ketujuh, iaitu Malaysia di pentas dunia. Murid mahu menulis kepentingan memberi sokongan kepada kepimpinan negara. Cikgu meminta kau memadankan faedah untuk diri, masyarakat dan negara.', 7, 703, 'malaysia_di_pentas_dunia.png'),
('e7_n3_s8', 'Halaman terakhir album. Cikgu meminta murid merumus nilai teras sivik unit ini. Dua nilai tertulis di bahagian atas, tetapi satu telah luntur.', 8, 703, 'bilik_mesyuarat_modern.png');
INSERT INTO Quest (questID, sceneID, questName, instruction, questType, description, questContent) VALUES
(701, 'e7_n1_s1', 'Nota Jawatan Perdana Menteri', 'Baca nota dan tentukan siapa yang melantik Perdana Menteri dan apakah jawatannya.', '5', 'Memahami jawatan Perdana Menteri: ketua kerajaan, dilantik oleh Yang di-Pertuan Agong, perlu sokongan majoriti Ahli Dewan Rakyat, diwujudkan selepas 31 Ogos 1957.', '{"clueText": "Nota: Perdana Menteri mengetuai pentadbiran negara. Beliau dilantik secara rasmi oleh Yang di-Pertuan Agong dan perlu mendapat sokongan majoriti Ahli Dewan Rakyat. Jawatan ini diwujudkan selepas Tanah Melayu merdeka pada 31 Ogos 1957.", "options": [{"text": "Ketua kerajaan yang dilantik oleh Yang di-Pertuan Agong.", "isCorrect": true}, {"text": "Ketua negara yang dipilih terus oleh rakyat.", "isCorrect": false, "consequence": "Nota menyatakan sebaliknya. Penerbit menggeleng."}, {"text": "Ketua negara yang dilantik oleh Menteri Besar.", "isCorrect": false, "consequence": "Menteri Besar tidak melantik Perdana Menteri. Yang di-Pertuan Agong yang melantik."}, {"text": "Ketua pembesar yang menggantikan Bendahara pada tahun 1511.", "isCorrect": false, "consequence": "Jawatan Perdana Menteri diwujudkan pada 1957, bukan 1511."}], "aftermath": "Skrip tersalah dan siaran menyatakan Perdana Menteri dipilih terus oleh rakyat. Penonton keliru.", "turns": [{"after": 7, "options": [{"text": "Ketua kerajaan mesti disokong majoriti Dewan Rakyat dan dilantik oleh Agong.", "isCorrect": true, "reaction": "Betul. Penerbit mencatat skrip baharu."}, {"text": "Perdana Menteri boleh memerintah tanpa sokongan sesiapa, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Penerbit membantah. Sokongan majoriti Dewan Rakyat diperlukan."}, {"text": "Perdana Menteri sama dengan Bendahara, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Itu jawatan zaman Kesultanan Melayu Melaka. Rakaman dihentikan."}], "clue": "Dilantik Agong, disokong majoriti."}]}'),
(702, 'e7_n1_s2', 'Pita Empat Perdana Menteri Pertama', 'Susun empat Perdana Menteri pertama mengikut tarikh mereka mula berkhidmat.', '1', 'Menyusun kronologi: Tunku (31 Ogos 1957), Tun Razak (22 Sep 1970), Tun Hussein (15 Jan 1976), Tun Dr. Mahathir (16 Julai 1981).', '{"timelineItems": [{"id": 1, "year": "31 Ogos 1957", "text": "Tunku Abdul Rahman menjadi Perdana Menteri pertama", "why": "Perdana Menteri pertama selepas merdeka."}, {"id": 2, "year": "22 September 1970", "text": "Tun Abdul Razak menjadi Perdana Menteri kedua", "why": "Beliau menggantikan Tunku."}, {"id": 3, "year": "15 Januari 1976", "text": "Tun Hussein Onn menjadi Perdana Menteri ketiga", "why": "Beliau menggantikan Tun Razak."}, {"id": 4, "year": "16 Julai 1981", "text": "Tun Dr. Mahathir menjadi Perdana Menteri keempat", "why": "Beliau menggantikan Tun Hussein."}], "aftermath": "Pita tersusun salah dan siaran memperkenalkan Perdana Menteri dengan urutan yang songsang.", "turns": [{"after": 8, "options": [{"text": "Menurut aku, kita menyusun mengikut tarikh supaya penonton memahami urutan pemimpin.", "isCorrect": true, "reaction": "Betul. Kerja kau teratur."}, {"text": "Aku fikir nama pemimpin sahaja sudah memadai tanpa tarikh, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Penerbit menggeleng. Tarikh membezakan giliran setiap pemimpin."}, {"text": "Sebenarnya, mana-mana susunan pun sama, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Penonton akan keliru tentang urutan pemimpin negara."}], "clue": "Tarikh menentukan urutan."}]}'),
(703, 'e7_n1_s3', 'Cari Bukti Laungan Merdeka', 'Cari empat bukti dalam rakaman laungan kemerdekaan.', '2', 'Mengenal pasti bukti pencapaian Tunku: memperjuangkan kemerdekaan secara rundingan dan laungan kemerdekaan di Stadium Merdeka pada 31 Ogos 1957.', '{"bgImage": "../assets/gameAsset/background/laungan_di_stadium_merdeka.png", "hotspots": [{"name": "Tunku di podium: memperjuangkan kemerdekaan secara rundingan", "top": "35%", "left": "52%"}, {"name": "Papan Perisytiharan Kemerdekaan Malaya di podium", "top": "69.4%", "left": "50.4%"}, {"name": "Poster Merdeka! Malaya! yang dipegang rakyat", "top": "46.5%", "left": "8.7%"}, {"name": "Rakyat bersorak dan mengangkat tangan menyambut kemerdekaan", "top": "59.4%", "left": "73.3%"}], "aftermath": "Bukti tidak ditemui dan siaran gagal menunjukkan bahawa kemerdekaan dicapai secara rundingan.", "turns": [{"after": 6, "options": [{"text": "Aku fikir kemerdekaan dicapai secara rundingan dan rakyat menyambutnya dengan gembira.", "isCorrect": true, "reaction": "Betul. Rakaman ini bukti sejarah."}, {"text": "Kemerdekaan dicapai melalui peperangan, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Tunku membetulkan. Beliau berunding secara aman."}, {"text": "Rakyat tidak menyambut kemerdekaan, jadi cukup dibiarkan begitu sahaja dan biarkan sahaja.", "isCorrect": false, "reaction": "Rakaman menunjukkan rakyat bersorak sambil mengangkat tangan."}], "clue": "Rundingan dan sambutan rakyat."}]}'),
(704, 'e7_n1_s4', 'Biodata Tunku Abdul Rahman', 'Padankan biodata Tunku dengan maklumat yang betul.', '4', 'Memahami biodata Tunku: lahir 8 Februari 1903 di Alor Setar; belajar di Penang Free School dan Universiti Cambridge (undang-undang); Ketua Menteri 1955; Bapa Kemerdekaan.', '{"pairs": [{"text": "Tempat lahir", "pair": 1}, {"text": "Alor Setar, Kedah", "pair": 1}, {"text": "Pelajaran tinggi", "pair": 2}, {"text": "Universiti Cambridge dalam bidang undang-undang", "pair": 2}, {"text": "Jawatan pada tahun 1955", "pair": 3}, {"text": "Ketua Menteri Persekutuan Tanah Melayu", "pair": 3}, {"text": "Gelaran", "pair": 4}, {"text": "Bapa Kemerdekaan", "pair": 4}, {"text": "Pernah berkhidmat sebagai", "pair": 5}, {"text": "Pegawai Daerah di Padang Terap, Langkawi dan Sungai Petani", "pair": 5}], "aftermath": "Biodata tersilap dan siaran memperkenalkan Tunku dengan gelaran yang salah. Penonton menghantar teguran.", "turns": [{"after": 7, "options": [{"text": "Sebenarnya, biodata yang tepat menghormati jasa pemimpin dan mengelakkan salah faham.", "isCorrect": true, "reaction": "Betul. Kita semak sebelum bersiaran."}, {"text": "Biodata tidak penting kerana Tunku terkenal dan tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Penerbit menggeleng. Setiap fakta perlu betul."}, {"text": "Gelaran boleh ditukar mengikut cita rasa penyiar, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Penonton menegur kerana gelaran itu ada sebab sejarahnya."}], "clue": "Biodata mesti tepat."}]}'),
(705, 'e7_n1_s5', 'Nota Pencapaian Tun Razak', 'Baca nota dan tentukan pencapaian Tun Razak selepas peristiwa 13 Mei 1969.', '5', 'Memahami pencapaian Tun Razak: mengembalikan keamanan melalui MAGERAN dan memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan dan menyusun semula masyarakat berbilang kaum.', '{"clueText": "Nota: Selepas peristiwa 13 Mei 1969, Tun Abdul Razak mengembalikan keamanan negara melalui pentadbiran Majlis Gerakan Negara (MAGERAN). Beliau memperkenalkan Dasar Ekonomi Baru (DEB) untuk membasmi kemiskinan rakyat dan menyusun semula masyarakat berbilang kaum.", "options": [{"text": "Menubuhkan MAGERAN dan memperkenalkan DEB.", "isCorrect": true}, {"text": "Menutup semua pejabat kerajaan.", "isCorrect": false, "consequence": "Nota tidak menyebut perkara itu. Skrip dibuang."}, {"text": "Memperkenalkan Program Rukun Tetangga dan Amanah Saham Nasional.", "isCorrect": false, "consequence": "Itu pencapaian Tun Hussein Onn."}, {"text": "Membina Putrajaya dan KLIA.", "isCorrect": false, "consequence": "Itu pencapaian Tun Dr. Mahathir."}], "aftermath": "Skrip tersalah dan siaran menyatakan Tun Razak menutup pejabat. Penonton marah.", "turns": [{"after": 5, "options": [{"text": "Aku fikir beliau memulihkan keamanan dan membasmi kemiskinan supaya masyarakat berbilang kaum seimbang.", "isCorrect": true, "reaction": "Betul. Itulah sebab beliau digelar Bapa Pembangunan."}, {"text": "Menurut aku, beliau memulihkan keamanan dengan menyekat semua kegiatan ekonomi, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Itu tidak benar. DEB bertujuan membasmi kemiskinan."}, {"text": "Pada pendapat aku, beliau hanya membina bangunan tanpa mengubah dasar, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Tun Razak memperkenalkan dasar, bukan hanya bangunan."}], "clue": "Keamanan dan DEB."}]}'),
(706, 'e7_n1_s6', 'Biodata Tun Abdul Razak', 'Padankan biodata Tun Abdul Razak dengan maklumat yang betul.', '4', 'Memahami biodata Tun Razak: lahir 11 Mac 1922 di Pulau Keladi, Pekan, Pahang; Kolej Melayu Kuala Kangsar, Raffles College, Lincoln''s Inn; Menteri Besar Pahang; PM 22 Sep 1970-14 Jan 1976; Bapa Pembangunan.', '{"pairs": [{"text": "Tempat lahir", "pair": 1}, {"text": "Pulau Keladi, Pekan, Pahang", "pair": 1}, {"text": "Pelajaran di Perak", "pair": 2}, {"text": "Kolej Melayu Kuala Kangsar", "pair": 2}, {"text": "Pelajaran undang-undang", "pair": 3}, {"text": "Lincoln''s Inn, London", "pair": 3}, {"text": "Jawatan di negerinya", "pair": 4}, {"text": "Setiausaha Kerajaan Negeri Pahang dan Menteri Besar Pahang", "pair": 4}, {"text": "Gelaran", "pair": 5}, {"text": "Bapa Pembangunan", "pair": 5}], "aftermath": "Biodata tersilap dan siaran menyatakan Tun Razak belajar di Cambridge. Penonton menegur.", "turns": [{"after": 7, "options": [{"text": "Kita menghargai pemimpin dengan mengetahui perjalanan hidup mereka.", "isCorrect": true, "reaction": "Betul. Itu tanda hormat."}, {"text": "Menurut aku, biodata pemimpin tidak perlu dipelajari, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Penerbit terkilan. Latar pemimpin membantu kita menghargai jasa."}, {"text": "Bagi aku, cukup mengetahui nama sahaja, jadi orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Siaran menjadi cetek dan mengelirukan."}], "clue": "Pelajari latar hidup pemimpin."}]}'),
(707, 'e7_n1_s7', 'Pencapaian Tun Hussein Onn', 'Padankan pencapaian dan biodata Tun Hussein Onn.', '4', 'Memahami Tun Hussein: Amanah Saham Nasional Berhad (bumiputera memiliki saham), Program Rukun Tetangga (perpaduan rakyat), lahir 12 Feb 1922 di Johor Bahru; PM 15 Jan 1976-16 Jul 1981; Bapa Perpaduan.', '{"pairs": [{"text": "Amanah Saham Nasional Berhad", "pair": 1}, {"text": "Memudahkan kaum bumiputera memiliki saham dalam syarikat berhad", "pair": 1}, {"text": "Program Rukun Tetangga", "pair": 2}, {"text": "Menggalakkan perpaduan dalam kalangan rakyat berbilang kaum", "pair": 2}, {"text": "Gelaran", "pair": 3}, {"text": "Bapa Perpaduan", "pair": 3}, {"text": "Tempoh jawatan", "pair": 4}, {"text": "15 Januari 1976 hingga 16 Julai 1981", "pair": 4}, {"text": "Tempat lahir", "pair": 5}, {"text": "Johor Bahru, Johor", "pair": 5}], "aftermath": "Pencapaian tersilap dan siaran memberikan jasa Tun Hussein kepada pemimpin lain.", "turns": [{"after": 7, "options": [{"text": "Pada pendapat aku, program yang menyatukan rakyat berbilang kaum patut diteruskan.", "isCorrect": true, "reaction": "Betul. Itulah warisan Bapa Perpaduan."}, {"text": "Menurut aku, program perpaduan hanya untuk satu kaum, jadi orang lain tidak perlu tahu.", "isCorrect": false, "reaction": "Rukun Tetangga menggalakkan perpaduan rakyat berbilang kaum."}, {"text": "Tun Hussein tidak melakukan apa-apa untuk perpaduan, kerana itu bukan urusan kita.", "isCorrect": false, "reaction": "Penerbit membetulkan. Beliau memperkenalkan Rukun Tetangga."}], "clue": "Program perpaduan untuk semua."}]}'),
(708, 'e7_n1_s8', 'Papan Gelaran Pemimpin', 'Padankan gelaran dengan pemimpinnya.', '4', 'Mengenal pasti gelaran: Tunku (Bapa Kemerdekaan), Tun Razak (Bapa Pembangunan), Tun Hussein (Bapa Perpaduan), Tun Dr. Mahathir (Bapa Pemodenan), Tun Abdullah (Bapa Pembangunan Modal Insan).', '{"pairs": [{"text": "Bapa Kemerdekaan", "pair": 1}, {"text": "Tunku Abdul Rahman", "pair": 1}, {"text": "Bapa Pembangunan", "pair": 2}, {"text": "Tun Abdul Razak", "pair": 2}, {"text": "Bapa Perpaduan", "pair": 3}, {"text": "Tun Hussein Onn", "pair": 3}, {"text": "Bapa Pemodenan", "pair": 4}, {"text": "Tun Dr. Mahathir Mohamad", "pair": 4}, {"text": "Bapa Pembangunan Modal Insan", "pair": 5}, {"text": "Tun Abdullah Ahmad Badawi", "pair": 5}], "aftermath": "Gelaran bertukar dan Tun Abdullah digelar Bapa Pemodenan di skrin. Penonton menegur.", "turns": [{"after": 7, "options": [{"text": "Pada pendapat aku, setiap gelaran mencerminkan sumbangan utama pemimpin itu kepada negara.", "isCorrect": true, "reaction": "Betul. Siaran ditutup dengan ucapan terima kasih."}, {"text": "Aku fikir gelaran hanya hiasan tanpa makna, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Penerbit menggeleng. Setiap gelaran ada sumbangan di sebaliknya."}, {"text": "Rasanya, semua pemimpin berkongsi satu gelaran yang sama, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Setiap pemimpin mempunyai gelaran berbeza."}], "clue": "Gelaran mencerminkan sumbangan."}]}'),
(709, 'e7_n2_s1', 'Gambar dan Tugas Perdana Menteri', 'Padankan contoh dalam gambar dengan tugas Perdana Menteri.', '4', 'Memahami tugas PM: ketua pentadbir utama (mesyuarat Ketua Setiausaha), memastikan dasar pembangunan (Tun Razak meninjau Felda), hubungan diplomatik (Tun Hussein bertemu Anwar Sadat 1977), mencadangkan duta (watikah ke Rusia).', '{"pairs": [{"text": "Tun Dr. Mahathir bermesyuarat dengan Ketua-ketua Setiausaha Kementerian", "pair": 1}, {"text": "Menjadi ketua pentadbir utama yang merancang dan menyelaraskan dasar negara", "pair": 1}, {"text": "Tun Razak meninjau tanaman getah di Felda Lurah Bilut", "pair": 2}, {"text": "Memastikan dasar pembangunan dapat ditingkatkan demi kesejahteraan rakyat", "pair": 2}, {"text": "Tun Hussein bertemu Presiden Anwar Sadat pada 1977", "pair": 3}, {"text": "Menjalin hubungan diplomatik dan persahabatan dengan negara luar", "pair": 3}, {"text": "Watikah pelantikan duta Malaysia ke Rusia", "pair": 4}, {"text": "Mencadangkan pelantikan duta, diplomat dan konsulat", "pair": 4}], "aftermath": "Gambar dipadankan dengan tugas yang salah dan murid mencatat nota yang salah dalam buku.", "turns": [{"after": 7, "options": [{"text": "Setiap tugas Perdana Menteri bertujuan memajukan negara demi kesejahteraan rakyat.", "isCorrect": true, "reaction": "Betul, cikgu."}, {"text": "Perdana Menteri hanya bertugas pada hari perayaan, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Murid menggeleng. Tugas itu berterusan setiap hari."}, {"text": "Perdana Menteri tidak perlu bekerjasama dengan negara lain, kerana itu lebih senang.", "isCorrect": false, "reaction": "Itu salah. Hubungan diplomatik penting untuk negara."}], "clue": "Tugas demi kesejahteraan rakyat."}]}'),
(710, 'e7_n2_s2', 'Tugas Berkaitan Agong dan Jemaah Menteri', 'Padankan tugas Perdana Menteri dengan penerangannya.', '4', 'Memahami tugas PM: menasihati Agong, mengiringi Agong ke Mesyuarat Majlis Raja-Raja, mencadangkan senarai Jemaah Menteri, mempengerusikan mesyuarat Jemaah Menteri.', '{"pairs": [{"text": "Menasihati Yang di-Pertuan Agong", "pair": 1}, {"text": "Berkaitan pemerintahan negara", "pair": 1}, {"text": "Mengiringi Yang di-Pertuan Agong", "pair": 2}, {"text": "Ke Mesyuarat Majlis Raja-Raja", "pair": 2}, {"text": "Mencadangkan senarai Jemaah Menteri", "pair": 3}, {"text": "Untuk dilantik oleh Yang di-Pertuan Agong", "pair": 3}, {"text": "Mempengerusikan Mesyuarat Jemaah Menteri", "pair": 4}, {"text": "Mesyuarat pertama selepas merdeka dipengerusikan oleh Tunku", "pair": 4}], "aftermath": "Kad bertukar dan murid menyangka Perdana Menteri melantik dirinya sendiri sebagai Agong.", "turns": [{"after": 7, "options": [{"text": "Perdana Menteri mencadangkan dan Agong yang melantik Jemaah Menteri.", "isCorrect": true, "reaction": "Betul. Murid menyalin ke buku."}, {"text": "Perdana Menteri melantik Jemaah Menteri sendiri, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Agong yang melantik. Cikgu membetulkan."}, {"text": "Jemaah Menteri dipilih oleh murid sekolah, kerana itu lebih senang.", "isCorrect": false, "reaction": "Murid ketawa kerana jawapan itu tidak masuk akal."}], "clue": "Perdana Menteri mencadangkan."}]}'),
(711, 'e7_n2_s3', 'Biodata Tun Dr. Mahathir', 'Padankan biodata Tun Dr. Mahathir dengan maklumat yang betul.', '4', 'Memahami biodata Mahathir: lahir 10 Julai 1925 di Seberang Perak, Alor Setar; belajar perubatan di Singapura; Klinik MAHA 1957; Menteri Pelajaran; PM 16 Julai 1981-30 Oktober 2003; Bapa Pemodenan.', '{"pairs": [{"text": "Tempat lahir", "pair": 1}, {"text": "Seberang Perak, Alor Setar, Kedah", "pair": 1}, {"text": "Bidang pelajaran", "pair": 2}, {"text": "Perubatan di Singapura", "pair": 2}, {"text": "Klinik yang dibuka pada tahun 1957", "pair": 3}, {"text": "Klinik MAHA di Alor Setar", "pair": 3}, {"text": "Tempoh Perdana Menteri keempat", "pair": 4}, {"text": "16 Julai 1981 hingga 30 Oktober 2003", "pair": 4}, {"text": "Gelaran", "pair": 5}, {"text": "Bapa Pemodenan", "pair": 5}], "aftermath": "Biodata tersilap dan murid menulis Tun Dr. Mahathir belajar undang-undang. Cikgu terpaksa membetulkan.", "turns": [{"after": 6, "options": [{"text": "Pemimpin yang berpendidikan dan berpengalaman dapat mentadbir negara dengan sistematik.", "isCorrect": true, "reaction": "Betul. Murid mengangguk."}, {"text": "Pendidikan pemimpin tidak penting, jadi tidak payah difikirkan panjang dan biarkan sahaja.", "isCorrect": false, "reaction": "Cikgu menggeleng. Latar pendidikan menyumbang kepada pentadbiran yang berkesan."}, {"text": "Semua Perdana Menteri belajar bidang yang sama, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Murid menyemak dan mendapati bidang mereka berbeza."}], "clue": "Latar pemimpin menyumbang kepada pentadbiran."}]}'),
(712, 'e7_n2_s4', 'Cari Bukti Wawasan 2020', 'Cari empat bukti pencapaian negara di bawah kepimpinan Tun Dr. Mahathir.', '2', 'Memahami pencapaian Mahathir: Wawasan 2020 (Putrajaya, KLIA, Menara Berkembar Petronas di KLCC) dan sektor perindustrian berteknologi tinggi melalui HICOM.', '{"bgImage": "../assets/gameAsset/background/pencapaian_ekonomi_perhubungan_dan_perdagangan.png", "hotspots": [{"name": "Menara Berkembar Petronas (KLCC): dibina pada zaman Tun Dr. Mahathir", "top": "26.5%", "left": "22%"}, {"name": "Kilang moden: HICOM untuk industri berteknologi tinggi", "top": "45%", "left": "78%"}, {"name": "Papan carta menaik: Wawasan 2020 menuju kemajuan", "top": "22%", "left": "90%"}, {"name": "Jambatan layang dan jalan raya: pembangunan seperti KLIA dan Putrajaya", "top": "62%", "left": "38%"}], "aftermath": "Bukti tidak ditemui dan murid menyangka Wawasan 2020 hanyalah slogan.", "turns": [{"after": 6, "options": [{"text": "Wawasan 2020 bertujuan menjadikan Malaysia negara maju.", "isCorrect": true, "reaction": "Betul. Murid bersorak."}, {"text": "Sebenarnya, wawasan 2020 bertujuan menutup kilang.", "isCorrect": false, "reaction": "Gambar menunjukkan kilang moden HICOM. Cikgu membetulkan."}, {"text": "Wawasan 2020 tiada kaitan dengan pembangunan.", "isCorrect": false, "reaction": "Murid menggeleng kerana ia merangkumi Putrajaya dan KLIA."}], "clue": "Wawasan 2020: negara maju."}]}'),
(713, 'e7_n2_s5', 'Nota Perdana Menteri Ketujuh', 'Baca nota dan tentukan maklumat Tun Dr. Mahathir sebagai Perdana Menteri ketujuh.', '5', 'Memahami PM ke-7: Tun Dr. Mahathir kali kedua 10 Mei 2018-24 Feb 2020; Pengerusi PETRONAS dan Penasihat PROTON; lawatan ke Jepun, Thailand dan UK; Wawasan Kemakmuran Bersama 2030.', '{"clueText": "Nota: Tun Dr. Mahathir menjadi Perdana Menteri kali kedua pada 10 Mei 2018 hingga 24 Februari 2020. Beliau pernah berkhidmat sebagai Pengerusi PETRONAS dan Penasihat PROTON, melawat Jepun, Thailand dan United Kingdom serta memperkenalkan satu wawasan baharu.", "options": [{"text": "Wawasan Kemakmuran Bersama 2030.", "isCorrect": true}, {"text": "Wawasan 2020.", "isCorrect": false, "consequence": "Itu wawasan beliau pada kali pertama. Nota menyebut wawasan baharu."}, {"text": "Gagasan 1Malaysia.", "isCorrect": false, "consequence": "Itu diperkenalkan oleh Dato'' Sri Najib."}, {"text": "Konsep Keluarga Malaysia.", "isCorrect": false, "consequence": "Itu diperkenalkan oleh Dato'' Seri Ismail Sabri."}], "aftermath": "Nota tersalah baca dan murid menulis wawasan beliau sama dengan kali pertama.", "turns": [{"after": 7, "options": [{"text": "Rasanya, wawasan baharu itu bermatlamat memakmurkan semua rakyat.", "isCorrect": true, "reaction": "Betul, cikgu."}, {"text": "Sebenarnya, beliau berhenti bekerjasama dengan semua negara luar.", "isCorrect": false, "reaction": "Nota menyatakan sebaliknya. Beliau meneruskan kerjasama."}, {"text": "Beliau hanya sekali menjadi Perdana Menteri, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Murid membetulkan kerana beliau memegang jawatan itu dua kali."}], "clue": "Dua kali PM, wawasan baharu."}]}'),
(714, 'e7_n2_s6', 'Biodata Tun Abdullah Ahmad Badawi', 'Padankan biodata Tun Abdullah dengan maklumat yang betul.', '4', 'Memahami biodata Abdullah: lahir 26 Nov 1939 di Kampung Perlis, Bayan Lepas, Pulau Pinang; Pengajian Islam di Universiti Malaya; Setiausaha MAGERAN; PM 31 Okt 2003-3 Apr 2009; Bapa Pembangunan Modal Insan.', '{"pairs": [{"text": "Tempat lahir", "pair": 1}, {"text": "Kampung Perlis, Bayan Lepas, Pulau Pinang", "pair": 1}, {"text": "Bidang di Universiti Malaya", "pair": 2}, {"text": "Pengajian Islam", "pair": 2}, {"text": "Pernah berkhidmat sebagai", "pair": 3}, {"text": "Setiausaha Majlis Gerakan Negara (MAGERAN)", "pair": 3}, {"text": "Tempoh Perdana Menteri kelima", "pair": 4}, {"text": "31 Oktober 2003 hingga 3 April 2009", "pair": 4}, {"text": "Gelaran", "pair": 5}, {"text": "Bapa Pembangunan Modal Insan", "pair": 5}], "aftermath": "Biodata tersilap dan murid mengelirukan Tun Abdullah dengan pemimpin lain.", "turns": [{"after": 6, "options": [{"text": "Modal insan bermaksud membangunkan rakyat yang berilmu dan berakhlak.", "isCorrect": true, "reaction": "Betul. Itu sumbangan beliau."}, {"text": "Modal insan bermaksud membangunkan bangunan sahaja, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Gelaran itu berkaitan pembangunan manusia."}, {"text": "Modal insan bermaksud menambah cukai, kerana tiada siapa yang akan peduli.", "isCorrect": false, "reaction": "Itu salah. Modal insan ialah pembangunan rakyat."}], "clue": "Modal insan: pembangunan rakyat."}]}'),
(715, 'e7_n2_s7', 'Nota Koridor dan Integriti', 'Baca nota dan tentukan fungsi Pelan Integriti Nasional.', '5', 'Memahami pencapaian Abdullah: Koridor Wilayah Ekonomi (pembangunan ekonomi seimbang dan pelaburan besar, contoh Iskandar Malaysia di Johor) dan Pelan Integriti Nasional (masyarakat bermoral dan beretika).', '{"clueText": "Nota: Tun Abdullah memperkenalkan Koridor Wilayah Ekonomi untuk memastikan pembangunan ekonomi seimbang dan kemasukan pelaburan yang besar. Beliau juga memperkenalkan Pelan Integriti Nasional (PIN) sebagai pelan untuk membina masyarakat yang bermoral dan beretika.", "options": [{"text": "Pelan Integriti Nasional membina masyarakat yang bermoral dan beretika.", "isCorrect": true}, {"text": "Pelan Integriti Nasional membina Putrajaya dan KLIA.", "isCorrect": false, "consequence": "Itu pencapaian Tun Dr. Mahathir."}, {"text": "Pelan Integriti Nasional membantu rakyat selepas PKP.", "isCorrect": false, "consequence": "Itu bantuan zaman Muhyiddin semasa COVID-19."}, {"text": "Pelan Integriti Nasional membasmi kemiskinan melalui DEB.", "isCorrect": false, "consequence": "DEB diperkenalkan oleh Tun Razak."}], "aftermath": "Nota tersalah baca dan murid menulis PIN ialah projek bangunan. Cikgu menggeleng.", "turns": [{"after": 6, "options": [{"text": "Pada pendapat aku, pembangunan perlu seimbang antara ekonomi dan akhlak.", "isCorrect": true, "reaction": "Betul. Cikgu tersenyum."}, {"text": "Pembangunan hanya perlu ekonomi tanpa akhlak, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Itu bertentangan dengan Pelan Integriti Nasional."}, {"text": "Pembangunan hanya perlu akhlak tanpa ekonomi, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Koridor Wilayah Ekonomi menjelaskan keperluan ekonomi juga."}], "clue": "Seimbang antara ekonomi dan akhlak."}]}'),
(716, 'e7_n2_s8', 'Biodata dan Pencapaian Dato'' Sri Najib', 'Padankan biodata dan pencapaian Dato'' Sri Najib dengan maklumat yang betul.', '4', 'Memahami PM ke-6: lahir 23 Julai 1953 di Kuala Lipis; St. John Institution; Universiti Nottingham (ekonomi industri); Menteri Besar Pahang; PM 3 Apr 2009-9 Mei 2018; Gagasan 1Malaysia dan GTP.', '{"pairs": [{"text": "Tempat lahir", "pair": 1}, {"text": "Kuala Lipis, Pahang", "pair": 1}, {"text": "Pelajaran tinggi", "pair": 2}, {"text": "Universiti Nottingham dalam bidang ekonomi industri", "pair": 2}, {"text": "Tempoh Perdana Menteri keenam", "pair": 3}, {"text": "3 April 2009 hingga 9 Mei 2018", "pair": 3}, {"text": "Gagasan 1Malaysia", "pair": 4}, {"text": "Memperkukuh hubungan dan kerjasama antara kaum", "pair": 4}, {"text": "Program Transformasi Kerajaan (GTP)", "pair": 5}, {"text": "Menjadikan negara berpendapatan tinggi selaras dengan Wawasan 2020", "pair": 5}], "aftermath": "Biodata tersilap dan murid menukar tujuan 1Malaysia dengan program lain.", "turns": [{"after": 7, "options": [{"text": "Gagasan itu menekankan kerjasama antara kaum demi kesejahteraan negara.", "isCorrect": true, "reaction": "Betul. Murid mencatat nota."}, {"text": "Pada pendapat aku, gagasan itu memisahkan kaum mengikut kawasan.", "isCorrect": false, "reaction": "Itu bertentangan. Gagasan 1Malaysia memperkukuh hubungan antara kaum."}, {"text": "Bagi aku, gagasan itu memberi keutamaan kepada satu kaum sahaja.", "isCorrect": false, "reaction": "Motonya mendahulukan rakyat."}], "clue": "Memperkukuh hubungan antara kaum."}]}'),
(717, 'e7_n2_s9', 'Dua Pemimpin Zaman COVID-19', 'Padankan Muhyiddin dan Ismail Sabri dengan biodata dan sumbangan mereka.', '4', 'Memahami PM ke-8 dan ke-9: Muhyiddin (Muar; MTE; bantuan kewangan semasa PKP; 1 Mac 2020-16 Ogos 2021) dan Ismail Sabri (Temerloh; peguam; Keluarga Malaysia; mula 20 Ogos 2021).', '{"pairs": [{"text": "Tan Sri Muhyiddin Md Yassin", "pair": 1}, {"text": "Dilahirkan di Muar, Johor; PM 1 Mac 2020 hingga 16 Ogos 2021", "pair": 1}, {"text": "Majlis Tindakan Ekonomi (MTE)", "pair": 2}, {"text": "Menggalakkan pertumbuhan sosioekonomi dan meningkatkan pelaburan", "pair": 2}, {"text": "Dato'' Seri Ismail Sabri Yaakob", "pair": 3}, {"text": "Dilahirkan di Temerloh, Pahang; PM mulai 20 Ogos 2021", "pair": 3}, {"text": "Konsep Keluarga Malaysia", "pair": 4}, {"text": "Meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia", "pair": 4}], "aftermath": "Padanan tersilap dan murid menukar sumbangan kedua-dua pemimpin. Cikgu menggeleng.", "turns": [{"after": 7, "options": [{"text": "Pemimpin prihatin membantu rakyat dan meraikan kepelbagaian.", "isCorrect": true, "reaction": "Betul, cikgu."}, {"text": "Pemimpin tidak perlu membantu rakyat semasa kecemasan.", "isCorrect": false, "reaction": "Murid membantah. Bantuan semasa PKP membantu rakyat."}, {"text": "Keluarga Malaysia hanya untuk satu agama, kerana itu lebih senang.", "isCorrect": false, "reaction": "Konsep itu meraikan pelbagai agama, bangsa, kaum dan usia."}], "clue": "Prihatin dan keterangkuman."}]}'),
(718, 'e7_n3_s1', 'Nota Bendahara dan Perdana Menteri', 'Baca nota dan tentukan perbandingan antara Bendahara dan Perdana Menteri.', '5', 'Memahami imbas kembali: pada zaman Kesultanan Melayu Melaka, Bendahara ialah Ketua Pembesar kerajaan; kini pentadbiran diketuai Perdana Menteri; jawatan PM diwujudkan selepas 31 Ogos 1957 dan kekal hingga kini.', '{"clueText": "Nota: Pada zaman Kesultanan Melayu Melaka, Bendahara merupakan Ketua Pembesar kerajaan. Pada masa ini, pentadbiran kerajaan diketuai oleh Perdana Menteri. Jawatan Perdana Menteri diwujudkan selepas Tanah Melayu mencapai kemerdekaan pada 31 Ogos 1957 dan kekal hingga hari ini.", "options": [{"text": "Dahulu Bendahara mengetuai pembesar, kini Perdana Menteri mengetuai pentadbiran.", "isCorrect": true}, {"text": "Dahulu Perdana Menteri mengetuai pembesar, kini Bendahara mengetuai pentadbiran.", "isCorrect": false, "consequence": "Susunan itu terbalik. Cikgu menggeleng."}, {"text": "Kedua-dua jawatan diwujudkan pada 1957.", "isCorrect": false, "consequence": "Jawatan Bendahara lebih tua daripada Perdana Menteri."}, {"text": "Kedua-dua jawatan tidak berkaitan dengan pentadbiran.", "isCorrect": false, "consequence": "Kedua-duanya mengetuai pentadbiran pada zaman masing-masing."}], "aftermath": "Nota tersalah baca dan album menyatakan Perdana Menteri wujud pada zaman Melaka.", "turns": [{"after": 6, "options": [{"text": "Kedua-dua jawatan mengetuai pentadbiran pada zaman masing-masing.", "isCorrect": true, "reaction": "Betul. Cikgu tersenyum."}, {"text": "Bendahara dan Perdana Menteri jawatan yang sama pada zaman yang sama.", "isCorrect": false, "reaction": "Zaman mereka berbeza."}, {"text": "Jawatan Perdana Menteri sudah dihapuskan, kerana itu lebih senang.", "isCorrect": false, "reaction": "Jawatan itu kekal hingga hari ini."}], "clue": "Jawatan kepala pentadbiran berubah mengikut zaman."}]}'),
(719, 'e7_n3_s2', 'Lima Perdana Menteri Terkini', 'Susun lima Perdana Menteri terkini mengikut tarikh mula berkhidmat.', '1', 'Menyusun kronologi: Abdullah (31 Okt 2003), Najib (3 Apr 2009), Mahathir kali kedua (10 Mei 2018), Muhyiddin (1 Mac 2020), Ismail Sabri (20 Ogos 2021).', '{"timelineItems": [{"id": 1, "year": "31 Oktober 2003", "text": "Tun Abdullah Ahmad Badawi menjadi Perdana Menteri kelima", "why": "Beliau menggantikan Tun Dr. Mahathir."}, {"id": 2, "year": "3 April 2009", "text": "Dato'' Sri Najib menjadi Perdana Menteri keenam", "why": "Beliau menggantikan Tun Abdullah."}, {"id": 3, "year": "10 Mei 2018", "text": "Tun Dr. Mahathir menjadi Perdana Menteri ketujuh kali kedua", "why": "Beliau kembali selepas Najib."}, {"id": 4, "year": "1 Mac 2020", "text": "Muhyiddin menjadi Perdana Menteri kelapan", "why": "Beliau menggantikan Tun Dr. Mahathir."}, {"id": 5, "year": "20 Ogos 2021", "text": "Dato'' Seri Ismail Sabri menjadi Perdana Menteri kesembilan", "why": "Beliau menggantikan Muhyiddin."}], "aftermath": "Kad bercampur dan album menyatakan Najib menjadi Perdana Menteri selepas Muhyiddin.", "turns": [{"after": 6, "options": [{"text": "Aku fikir sejak 1957 hingga 2021, negara kita mempunyai sembilan orang Perdana Menteri.", "isCorrect": true, "reaction": "Betul. Album lengkap."}, {"text": "Hanya lima orang Perdana Menteri sejak merdeka, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Itu salah. Kau baru menyusun lima daripada sembilan."}, {"text": "Tun Dr. Mahathir hanya sekali menjadi Perdana Menteri, jadi cukup dibiarkan begitu sahaja.", "isCorrect": false, "reaction": "Murid menyemak dan mendapati beliau dua kali."}], "clue": "Sembilan Perdana Menteri sejak 1957 hingga 2021."}]}'),
(720, 'e7_n3_s3', 'Nota Pencapaian Tunku', 'Baca nota dan tentukan dua pencapaian Tunku.', '5', 'Memahami pencapaian Tunku: memperjuangkan kemerdekaan secara rundingan dan merealisasikan pembentukan Malaysia pada 16 September 1963.', '{"clueText": "Nota: Tunku Abdul Rahman Putra Al-Haj memperjuangkan kemerdekaan negara secara rundingan. Beliau juga berjaya merealisasikan pembentukan Malaysia pada 16 September 1963.", "options": [{"text": "Memperjuangkan kemerdekaan secara rundingan dan merealisasikan pembentukan Malaysia.", "isCorrect": true}, {"text": "Menubuhkan MAGERAN dan memperkenalkan DEB.", "isCorrect": false, "consequence": "Itu pencapaian Tun Razak."}, {"text": "Membina Putrajaya dan KLIA.", "isCorrect": false, "consequence": "Itu pencapaian Tun Dr. Mahathir."}, {"text": "Memperkenalkan Program Transformasi Kerajaan.", "isCorrect": false, "consequence": "Itu program Dato'' Sri Najib."}], "aftermath": "Nota tersalah baca dan album menyatakan Tunku menubuhkan MAGERAN.", "turns": [{"after": 6, "options": [{"text": "Pemimpin yang berunding membawa negara kepada kemerdekaan secara aman.", "isCorrect": true, "reaction": "Betul. Itu contoh kepimpinan berwibawa."}, {"text": "Sebenarnya, kemerdekaan dicapai dengan peperangan, lagipun tiada akibatnya.", "isCorrect": false, "reaction": "Nota menyatakan kemerdekaan diperjuangkan secara rundingan."}, {"text": "Malaysia dibentuk pada 31 Ogos 1957, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Tarikh itu hari kemerdekaan. Malaysia dibentuk pada 16 September 1963."}], "clue": "Rundingan dan pembentukan Malaysia."}]}'),
(721, 'e7_n3_s4', 'Jadual Pencapaian Pemimpin', 'Padankan pemimpin dengan pencapaian utama mereka.', '4', 'Merumus pencapaian: Tunku (kemerdekaan secara rundingan), Razak (DEB), Hussein (Amanah Saham Nasional Berhad), Mahathir (Wawasan 2020), Abdullah (PIN), Najib (GTP).', '{"pairs": [{"text": "Tunku Abdul Rahman", "pair": 1}, {"text": "Memperjuangkan kemerdekaan secara rundingan", "pair": 1}, {"text": "Tun Abdul Razak", "pair": 2}, {"text": "Memperkenalkan Dasar Ekonomi Baru (DEB)", "pair": 2}, {"text": "Tun Hussein Onn", "pair": 3}, {"text": "Memperkenalkan Amanah Saham Nasional Berhad", "pair": 3}, {"text": "Tun Dr. Mahathir", "pair": 4}, {"text": "Merealisasikan Wawasan 2020 melalui Putrajaya, KLIA dan KLCC", "pair": 4}, {"text": "Tun Abdullah", "pair": 5}, {"text": "Memperkenalkan Pelan Integriti Nasional (PIN)", "pair": 5}, {"text": "Dato'' Sri Najib", "pair": 6}, {"text": "Melancarkan Program Transformasi Kerajaan (GTP)", "pair": 6}], "aftermath": "Padanan tersilap dan jadual memberi jasa Tun Razak kepada Tun Hussein. Cikgu memotong markah.", "turns": [{"after": 8, "options": [{"text": "Setiap pencapaian membawa kemajuan dan kesejahteraan kepada rakyat.", "isCorrect": true, "reaction": "Betul. Jadual dilengkapkan."}, {"text": "Pada pendapat aku, pencapaian itu hanya berguna kepada pemimpin sendiri.", "isCorrect": false, "reaction": "Cikgu menggeleng. Pencapaian itu demi kesejahteraan rakyat."}, {"text": "Rasanya, pencapaian tidak perlu dikenang, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Murid terdiam. Jasa pemimpin wajar dihargai."}], "clue": "Pencapaian demi rakyat."}]}'),
(722, 'e7_n3_s5', 'Kad Kepentingan Pemimpin Berwibawa', 'Baca kad dan tentukan kepentingan pemimpin yang memiliki ciri kepimpinan berwibawa.', '5', 'Memahami kepentingan pemimpin berwibawa: memajukan sistem ekonomi, menjamin keselamatan negara, membentuk kerajaan yang tersusun, menimbulkan rasa hormat, mewujudkan negara yang membangun, memudahkan pelaksanaan dasar.', '{"clueText": "Kad: Pemimpin yang berwibawa memajukan sistem ekonomi negara, menjamin keselamatan negara, membentuk kerajaan yang tersusun, menimbulkan rasa hormat antara pemimpin, mewujudkan negara yang membangun dan memudahkan pelaksanaan dasar-dasar pembangunan negara.", "options": [{"text": "Memajukan ekonomi, menjamin keselamatan dan membentuk kerajaan tersusun.", "isCorrect": true}, {"text": "Memecahkan perpaduan dan melemahkan keselamatan.", "isCorrect": false, "consequence": "Itu bertentangan dengan kad."}, {"text": "Menyukarkan pelaksanaan dasar-dasar pembangunan.", "isCorrect": false, "consequence": "Kad menyatakan sebaliknya."}, {"text": "Menimbulkan rasa curiga antara pemimpin.", "isCorrect": false, "consequence": "Kad menyebut menimbulkan rasa hormat."}], "aftermath": "Kad tersalah baca dan album menulis pemimpin berwibawa melemahkan keselamatan.", "turns": [{"after": 6, "options": [{"text": "Pemimpin berwibawa melahirkan negara yang maju dan selamat.", "isCorrect": true, "reaction": "Betul. Murid menulis dalam album."}, {"text": "Aku fikir pemimpin tidak perlu berwibawa asalkan terkenal.", "isCorrect": false, "reaction": "Cikgu menggeleng. Kewibawaan penting untuk pentadbiran."}, {"text": "Pemimpin berwibawa hanya untuk menghias ucapan, jadi lupakan sahaja.", "isCorrect": false, "reaction": "Kad menunjukkan ia memberi manfaat nyata."}], "clue": "Berwibawa untuk negara maju."}]}'),
(723, 'e7_n3_s6', 'Kad Cara Menghargai Pemimpin', 'Baca kad dan tentukan cara menunjukkan penghargaan kepada Perdana Menteri.', '5', 'Memahami cara menghargai pemimpin: mengeratkan perpaduan antara kaum, mengekalkan taat setia terhadap pemimpin, menjaga nama baik negara, menjaga keamanan negara.', '{"clueText": "Kad: Kita boleh menunjukkan penghargaan kepada Perdana Menteri dengan mengeratkan perpaduan antara kaum, mengekalkan taat setia terhadap pemimpin, menjaga nama baik negara dan menjaga keamanan negara.", "options": [{"text": "Mengeratkan perpaduan antara kaum dan menjaga nama baik negara.", "isCorrect": true}, {"text": "Memecahkan perpaduan antara kaum.", "isCorrect": false, "consequence": "Itu bertentangan dengan kad."}, {"text": "Mencemarkan nama baik negara.", "isCorrect": false, "consequence": "Itu menjatuhkan maruah negara."}, {"text": "Mengabaikan keamanan negara.", "isCorrect": false, "consequence": "Kad menyatakan kita menjaga keamanan."}], "aftermath": "Kad tersalah baca dan murid menulis cara yang tidak menghargai pemimpin.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, kita menghormati pemimpin dengan menjaga perpaduan dan keamanan negara.", "isCorrect": true, "reaction": "Betul. Itulah tanda penghargaan."}, {"text": "Kita menghormati pemimpin dengan menyebarkan fitnah, kerana kita tidak rugi apa-apa.", "isCorrect": false, "reaction": "Fitnah memecahkan perpaduan dan mencemarkan nama baik negara."}, {"text": "Rasanya, kita tidak perlu menghargai pemimpin, jadi tidak payah difikirkan panjang.", "isCorrect": false, "reaction": "Jasa pemimpin wajar dihargai demi kesejahteraan negara."}], "clue": "Hargai dengan perpaduan dan keamanan."}]}'),
(724, 'e7_n3_s7', 'Diri, Masyarakat dan Negara', 'Padankan peringkat diri, masyarakat dan negara dengan faedah menyokong pemimpin.', '4', 'Memahami cinta akan negara: diri menghormati pemimpin; masyarakat yang menyokong pemimpin berwibawa menjadi bertanggungjawab kepada negara; sikap bertanggungjawab memastikan kedaulatan negara kekal terpelihara.', '{"pairs": [{"text": "Diri", "pair": 1}, {"text": "Kita perlu menghormati pemimpin negara", "pair": 1}, {"text": "Masyarakat", "pair": 2}, {"text": "Sokongan kepada pemimpin berwibawa melahirkan masyarakat bertanggungjawab", "pair": 2}, {"text": "Negara", "pair": 3}, {"text": "Sikap bertanggungjawab memastikan kedaulatan negara terpelihara", "pair": 3}], "aftermath": "Padanan tersilap dan album menyatakan hormat pemimpin hanya urusan negara. Cikgu membetulkan.", "turns": [{"after": 6, "options": [{"text": "Sokongan kepada pemimpin menjamin keamanan, kestabilan dan pembangunan negara.", "isCorrect": true, "reaction": "Betul. Album selesai."}, {"text": "Pada pendapat aku, sokongan kepada pemimpin menyebabkan kekacauan.", "isCorrect": false, "reaction": "Sokongan menjamin keamanan dan keharmonian."}, {"text": "Sokongan kepada pemimpin tidak perlu kerana tidak membawa kesan dan lupakan sahaja.", "isCorrect": false, "reaction": "Kestabilan politik dan ekonomi bergantung pada sokongan rakyat."}], "clue": "Sokongan menjamin kestabilan."}]}'),
(725, 'e7_n3_s8', 'Nota Nilai Teras Sivik', 'Baca nota dan tentukan dua nilai teras sivik dalam unit Pemimpin Negara.', '5', 'Memahami nilai teras sivik Unit 7: bertanggungjawab dan hormat-menghormati.', '{"clueText": "Nota: Unit ini mengajar kita menghargai jasa pemimpin yang memajukan negara. Kita perlu menghormati pemimpin dan bersikap bertanggungjawab terhadap negara supaya kedaulatan negara dan perpaduan rakyat kekal terpelihara.", "options": [{"text": "Bertanggungjawab dan hormat-menghormati.", "isCorrect": true}, {"text": "Bersaing dan berebut kuasa.", "isCorrect": false, "consequence": "Nota tidak menyebut nilai itu."}, {"text": "Menyindir dan memperlekeh pemimpin.", "isCorrect": false, "consequence": "Itu bertentangan dengan hormat-menghormati."}, {"text": "Mementingkan diri sendiri.", "isCorrect": false, "consequence": "Itu bertentangan dengan bertanggungjawab."}], "aftermath": "Nota tersalah baca dan album mencatat nilai yang bertentangan dengan unit ini.", "turns": [{"after": 6, "options": [{"text": "Sebenarnya, hormati pemimpin dan bertanggungjawab terhadap negara.", "isCorrect": true, "reaction": "Betul. Album kau layak mendapat markah penuh."}, {"text": "Hormat pemimpin hanya apabila mereka ada di hadapan kita, jadi biarkan sahaja.", "isCorrect": false, "reaction": "Cikgu menggeleng. Hormat berterusan."}, {"text": "Pada pendapat aku, tanggungjawab hanya untuk orang dewasa.", "isCorrect": false, "reaction": "Cikgu menegur. Setiap warganegara bertanggungjawab."}], "clue": "Hormat dan bertanggungjawab."}]}');
INSERT INTO LearningSupport (questID, sceneID, supportType, hint, explanation, feedback) VALUES
(NULL, 'e7_n1_s1', 'hint', 'Jawatan itu diwujudkan selepas merdeka pada 31 Ogos 1957.', NULL, NULL),
(701, NULL, 'hint', 'Perdana Menteri dilantik oleh Yang di-Pertuan Agong dan mesti disokong majoriti Dewan Rakyat.', 'Di studio siaran khas aku membetulkan skrip wartawan muda. Perdana Menteri ialah ketua kerajaan yang dilantik secara rasmi oleh Yang di-Pertuan Agong dan perlu mendapat sokongan majoriti Ahli Dewan Rakyat, dan jawatan itu diwujudkan selepas merdeka pada 31 Ogos 1957.', 'Tepat! Wartawan muda memadam ayat yang salah dan lampu merah siaran pun menyala.'),
(NULL, 'e7_n1_s2', 'hint', 'Tunku, Tun Razak, Tun Hussein, kemudian Tun Dr. Mahathir.', NULL, NULL),
(702, NULL, 'hint', 'Mulakan dengan 31 Ogos 1957. Seterusnya 1970, 1976, dan 1981.', 'Empat Perdana Menteri pertama menyebut tarikh mereka sendiri. Tunku Abdul Rahman pada 31 Ogos 1957, Tun Abdul Razak pada 22 September 1970, Tun Hussein Onn pada 15 Januari 1976 dan Tun Dr. Mahathir pada 16 Julai 1981.', 'Betul! Pita itu tersusun semula dan para pemimpin tersenyum melihat giliran masing-masing dihormati.'),
(NULL, 'e7_n1_s3', 'hint', 'Kemerdekaan dicapai secara rundingan. Rakyat menyambutnya dengan sorakan.', NULL, NULL),
(703, NULL, 'hint', 'Empat bukti. Tunku di podium, papan perisytiharan, poster Merdeka! Malaya! dan rakyat yang bersorak.', 'Dalam rakaman laungan kemerdekaan aku menjumpai empat bukti. Tunku di podium Stadium Merdeka, papan Perisytiharan Kemerdekaan Malaya, poster Merdeka! Malaya! yang dipegang rakyat dan rakyat yang bersorak menyambut kemerdekaan.', 'Mata yang tajam! Tunku tersenyum apabila rakaman itu akhirnya jelas di skrin.'),
(NULL, 'e7_n1_s4', 'hint', 'Pegawai Daerah di Padang Terap, Langkawi dan Sungai Petani.', NULL, NULL),
(704, NULL, 'hint', 'Lahir di Alor Setar. Belajar undang-undang di Cambridge. Ketua Menteri pada 1955. Bapa Kemerdekaan.', 'Tunku sendiri menceritakan biodatanya. Beliau lahir di Alor Setar, belajar undang-undang di Universiti Cambridge, pernah menjadi Pegawai Daerah di Padang Terap, Langkawi dan Sungai Petani, Ketua Menteri pada 1955 dan digelar Bapa Kemerdekaan.', 'Tepat! Tunku mengangguk puas kerana biodatanya disampaikan dengan betul.'),
(NULL, 'e7_n1_s5', 'hint', 'MAGERAN mengembalikan keamanan. DEB membasmi kemiskinan.', NULL, NULL),
(705, NULL, 'hint', 'Selepas 13 Mei 1969, Tun Razak menubuhkan satu majlis untuk memulihkan keamanan dan memperkenalkan satu dasar ekonomi.', 'Tun Abdul Razak membetulkan skrip siaran. Selepas peristiwa 13 Mei 1969, beliau mengembalikan keamanan melalui MAGERAN dan memperkenalkan Dasar Ekonomi Baru untuk membasmi kemiskinan serta menyusun semula masyarakat berbilang kaum.', 'Betul! Tun Razak mengangguk dan skrip yang salah itu dicampak ke dalam bakul.'),
(NULL, 'e7_n1_s6', 'hint', 'Setiausaha Kerajaan Negeri Pahang dan Menteri Besar Pahang ialah jawatan beliau di negerinya.', NULL, NULL),
(706, NULL, 'hint', 'Pulau Keladi di Pekan, Pahang. Kolej Melayu Kuala Kangsar. Lincoln''s Inn, London. Bapa Pembangunan.', 'Tun Abdul Razak menceritakan latar hidupnya. Beliau lahir di Pulau Keladi, Pekan, Pahang, belajar di Kolej Melayu Kuala Kangsar dan Lincoln''s Inn London, pernah menjadi Setiausaha Kerajaan Negeri dan Menteri Besar Pahang, dan digelar Bapa Pembangunan.', 'Tepat sekali! Tun Razak tersenyum dan menunjukkan gambar rumah kelahirannya di Pulau Keladi.'),
(NULL, 'e7_n1_s7', 'hint', 'Tun Hussein lahir di Johor Bahru dan digelar Bapa Perpaduan.', NULL, NULL),
(707, NULL, 'hint', 'ASN memudahkan bumiputera memiliki saham. Rukun Tetangga menggalakkan perpaduan.', 'Tun Hussein Onn menerangkan sumbangannya. Beliau memperkenalkan Amanah Saham Nasional Berhad untuk memudahkan bumiputera memiliki saham dan Program Rukun Tetangga untuk menggalakkan perpaduan, lahir di Johor Bahru, memerintah dari 15 Januari 1976 hingga 16 Julai 1981 dan digelar Bapa Perpaduan.', 'Betul! Tun Hussein tersenyum kerana ASN dan Rukun Tetangga tidak lagi tertukar.'),
(NULL, 'e7_n1_s8', 'hint', 'Pemodenan bersama Tun Dr. Mahathir. Modal Insan bersama Tun Abdullah.', NULL, NULL),
(708, NULL, 'hint', 'Kemerdekaan bersama Tunku. Pembangunan bersama Razak. Perpaduan bersama Hussein.', 'Siaran khas ditutup dengan gelaran para pemimpin. Tunku ialah Bapa Kemerdekaan, Tun Razak Bapa Pembangunan, Tun Hussein Bapa Perpaduan, Tun Dr. Mahathir Bapa Pemodenan dan Tun Abdullah Bapa Pembangunan Modal Insan.', 'Tahniah! Lima pemimpin berdiri dan menunduk hormat apabila siaran khas itu tamat.'),
(NULL, 'e7_n2_s1', 'hint', 'Mencadangkan duta, diplomat dan konsulat ialah tugas berkaitan watikah.', NULL, NULL),
(709, NULL, 'hint', 'Mesyuarat dengan Ketua Setiausaha untuk dasar negara. Felda untuk pembangunan. Anwar Sadat untuk hubungan luar. Watikah untuk pelantikan duta.', 'Gambar dalam buku teks hidup dan para Perdana Menteri menerangkan tugas mereka. Tun Dr. Mahathir mengetuai pentadbiran dan menyelaraskan dasar, Tun Razak memastikan pembangunan ditingkatkan, Tun Hussein menjalin hubungan dengan negara luar, dan watikah duta menunjukkan Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat.', 'Hebat! Para pemimpin kembali ke muka surat masing-masing sambil mengangguk puas.'),
(NULL, 'e7_n2_s2', 'hint', 'Jemaah Menteri dicadangkan oleh Perdana Menteri dan dilantik oleh Yang di-Pertuan Agong.', NULL, NULL),
(710, NULL, 'hint', 'Menasihati Agong tentang pemerintahan. Mengiringi Agong ke Mesyuarat Majlis Raja-Raja.', 'Aku belajar hubungan Perdana Menteri dengan Yang di-Pertuan Agong. Perdana Menteri menasihati Agong tentang pemerintahan, mengiringi baginda ke Mesyuarat Majlis Raja-Raja, mencadangkan senarai Jemaah Menteri untuk dilantik oleh Agong, dan mempengerusikan Mesyuarat Jemaah Menteri yang pertama selepas merdeka dipengerusikan oleh Tunku.', 'Tepat! Yang di-Pertuan Agong mengangguk dan Cikgu menepuk tangan perlahan.'),
(NULL, 'e7_n2_s3', 'hint', 'Perdana Menteri keempat dari 16 Julai 1981 hingga 30 Oktober 2003. Bapa Pemodenan.', NULL, NULL),
(711, NULL, 'hint', 'Lahir di Seberang Perak, Alor Setar. Belajar perubatan di Singapura. Klinik MAHA dibuka pada 1957.', 'Tun Dr. Mahathir menceritakan latar hidupnya. Beliau lahir di Seberang Perak, Alor Setar, belajar perubatan di Singapura, membuka Klinik MAHA di Alor Setar pada 1957, menjadi Perdana Menteri keempat dari 16 Julai 1981 hingga 30 Oktober 2003, dan digelar Bapa Pemodenan.', 'Betul! Tun Dr. Mahathir tersenyum kerana kliniknya dari tahun 1957 masih diingati.'),
(NULL, 'e7_n2_s4', 'hint', 'Wawasan 2020 menuju kemajuan. KLIA dan Putrajaya ialah sebahagian pembangunannya.', NULL, NULL),
(712, NULL, 'hint', 'Empat bukti. Menara Berkembar Petronas, kilang HICOM, papan carta Wawasan 2020 dan jambatan layang.', 'Aku mencari bukti Wawasan 2020. Menara Berkembar Petronas di KLCC, kilang moden HICOM, papan carta menaik Wawasan 2020 dan jambatan layang serta jalan raya menunjukkan pembangunan seperti KLIA dan Putrajaya.', 'Cekap! Tun Dr. Mahathir menunjuk ke arah Menara Berkembar sambil tersenyum bangga.'),
(NULL, 'e7_n2_s5', 'hint', 'Nama wawasan itu ialah Wawasan Kemakmuran Bersama 2030.', NULL, NULL),
(713, NULL, 'hint', 'Perdana Menteri ketujuh memperkenalkan satu wawasan baharu untuk tahun 2030.', 'Tun Dr. Mahathir menjadi Perdana Menteri kali kedua, iaitu yang ketujuh, dari 10 Mei 2018 hingga 24 Februari 2020. Beliau pernah menjadi Pengerusi PETRONAS dan Penasihat PROTON, melawat Jepun, Thailand dan United Kingdom, dan memperkenalkan Wawasan Kemakmuran Bersama 2030.', 'Betul! Tun Dr. Mahathir mengangguk dan meletakkan tangan di atas muka surat wawasan itu.'),
(NULL, 'e7_n2_s6', 'hint', 'Perdana Menteri kelima dari 31 Oktober 2003 hingga 3 April 2009. Bapa Pembangunan Modal Insan.', NULL, NULL),
(714, NULL, 'hint', 'Lahir di Kampung Perlis, Bayan Lepas. Belajar Pengajian Islam. Pernah menjadi Setiausaha MAGERAN.', 'Tun Abdullah Ahmad Badawi menerangkan latar hidupnya. Beliau lahir di Kampung Perlis, Bayan Lepas, Pulau Pinang, belajar Pengajian Islam di Universiti Malaya, pernah menjadi Setiausaha MAGERAN, menjadi Perdana Menteri kelima dari 31 Oktober 2003 hingga 3 April 2009, dan digelar Bapa Pembangunan Modal Insan.', 'Tepat! Tun Abdullah tersenyum dan membetulkan songkoknya dengan hormat.'),
(NULL, 'e7_n2_s7', 'hint', 'PIN ialah Pelan Integriti Nasional.', NULL, NULL),
(715, NULL, 'hint', 'Koridor Wilayah Ekonomi untuk ekonomi seimbang dan pelaburan. PIN untuk masyarakat bermoral dan beretika.', 'Tun Abdullah menerangkan dua perkara. Koridor Wilayah Ekonomi memastikan pembangunan ekonomi seimbang dan kemasukan pelaburan yang besar, manakala Pelan Integriti Nasional membina masyarakat yang bermoral dan beretika.', 'Betul! Tun Abdullah mengangguk puas kerana fungsi kedua-dua perkara itu tidak lagi tertukar.'),
(NULL, 'e7_n2_s8', 'hint', 'Perdana Menteri keenam dari 3 April 2009 hingga 9 Mei 2018.', NULL, NULL),
(716, NULL, 'hint', 'Lahir di Kuala Lipis. Belajar di Nottingham. 1Malaysia memperkukuh kerjasama antara kaum. GTP untuk negara berpendapatan tinggi.', 'Dato'' Sri Najib menceritakan sumbangannya. Beliau lahir di Kuala Lipis, belajar ekonomi industri di Universiti Nottingham, menjadi Perdana Menteri keenam dari 3 April 2009 hingga 9 Mei 2018, memperkenalkan Gagasan 1Malaysia untuk memperkukuh kerjasama antara kaum, dan melancarkan GTP untuk menjadikan negara berpendapatan tinggi.', 'Tepat! Murid-murid mengulang moto Rakyat Didahulukan, Pencapaian Diutamakan beramai-ramai.'),
(NULL, 'e7_n2_s9', 'hint', 'Keluarga Malaysia meraikan pelbagai agama, bangsa, kaum dan usia.', NULL, NULL),
(717, NULL, 'hint', 'Muhyiddin dengan Muar dan MTE. Ismail Sabri dengan Temerloh dan Keluarga Malaysia.', 'Dua pemimpin zaman COVID-19 menceritakan diri mereka. Tan Sri Muhyiddin lahir di Muar, menjadi Perdana Menteri dari 1 Mac 2020 hingga 16 Ogos 2021 dan menubuhkan MTE, manakala Dato'' Seri Ismail Sabri lahir di Temerloh, menjadi Perdana Menteri mulai 20 Ogos 2021 dan memperkenalkan Keluarga Malaysia.', 'Betul! Para pemimpin saling mengangguk apabila buku teks itu akhirnya tertutup dengan tenang.'),
(NULL, 'e7_n3_s1', 'hint', 'Jawatan Perdana Menteri diwujudkan selepas 31 Ogos 1957.', NULL, NULL),
(718, NULL, 'hint', 'Bendahara pada zaman Kesultanan Melayu Melaka. Perdana Menteri selepas merdeka pada 1957.', 'Aku membandingkan dua jawatan dalam album. Pada zaman Kesultanan Melayu Melaka, Bendahara ialah Ketua Pembesar kerajaan, manakala kini pentadbiran diketuai oleh Perdana Menteri, jawatan yang diwujudkan selepas merdeka pada 31 Ogos 1957.', 'Tepat! Murid penyelidik itu menulis perbandingan dua zaman di halaman pertama albumnya.'),
(NULL, 'e7_n3_s2', 'hint', 'Najib 2009, Mahathir kali kedua 2018, Muhyiddin 2020.', NULL, NULL),
(719, NULL, 'hint', 'Mulakan dengan Tun Abdullah pada 2003. Penutupnya ialah Dato'' Seri Ismail Sabri pada 2021.', 'Aku melengkapkan album dengan lima Perdana Menteri terkini. Tun Abdullah pada 31 Oktober 2003, Dato'' Sri Najib pada 3 April 2009, Tun Dr. Mahathir kali kedua pada 10 Mei 2018, Muhyiddin pada 1 Mac 2020 dan Dato'' Seri Ismail Sabri pada 20 Ogos 2021.', 'Betul! Album itu kini mempunyai sembilan orang Perdana Menteri dari 1957 hingga 2021.'),
(NULL, 'e7_n3_s3', 'hint', 'Pembentukan Malaysia direalisasikan pada 16 September 1963.', NULL, NULL),
(720, NULL, 'hint', 'Dua pencapaian. Satu pada 1957 secara rundingan, satu lagi pada 16 September 1963.', 'Aku menulis dua pencapaian Tunku dalam album. Beliau memperjuangkan kemerdekaan negara secara rundingan dan berjaya merealisasikan pembentukan Malaysia pada 16 September 1963.', 'Tepat! Tunku tersenyum melihat dua pencapaiannya dicatat dengan teliti.'),
(NULL, 'e7_n3_s4', 'hint', 'DEB bersama Razak. ASN bersama Hussein. GTP bersama Najib.', NULL, NULL),
(721, NULL, 'hint', 'Tunku, Razak, Hussein, Mahathir, Abdullah dan Najib. Setiap seorang ada satu pencapaian utama.', 'Aku memadankan enam pemimpin dengan pencapaian. Tunku memperjuangkan kemerdekaan secara rundingan, Tun Razak memperkenalkan DEB, Tun Hussein memperkenalkan ASN, Tun Dr. Mahathir merealisasikan Wawasan 2020 melalui Putrajaya, KLIA dan KLCC, Tun Abdullah memperkenalkan PIN dan Dato'' Sri Najib melancarkan GTP.', 'Hebat! Keenam-enam pemimpin ditemukan dengan pencapaian mereka tanpa satu pun tersilap.'),
(NULL, 'e7_n3_s5', 'hint', 'Pemimpin berwibawa juga menimbulkan rasa hormat antara pemimpin.', NULL, NULL),
(722, NULL, 'hint', 'Kad itu menyebut ekonomi, keselamatan dan kerajaan yang tersusun.', 'Aku belajar kepentingan pemimpin berwibawa. Mereka memajukan sistem ekonomi negara, menjamin keselamatan negara, membentuk kerajaan yang tersusun, menimbulkan rasa hormat antara pemimpin, mewujudkan negara yang membangun dan memudahkan pelaksanaan dasar pembangunan.', 'Tepat! Murid penyelidik itu menyalin senarai itu ke halaman khas dalam albumnya.'),
(NULL, 'e7_n3_s6', 'hint', 'Taat setia dan menjaga keamanan negara juga termasuk.', NULL, NULL),
(723, NULL, 'hint', 'Kad itu menyebut perpaduan antara kaum dan nama baik negara.', 'Aku belajar empat cara menghargai Perdana Menteri. Kita mengeratkan perpaduan antara kaum, mengekalkan taat setia terhadap pemimpin, menjaga nama baik negara dan menjaga keamanan negara.', 'Betul! Cikgu mengangguk dan murid itu menulis empat cara itu dengan huruf besar.'),
(NULL, 'e7_n3_s7', 'hint', 'Tiga peringkat, iaitu diri, masyarakat dan negara.', NULL, NULL),
(724, NULL, 'hint', 'Diri dengan menghormati pemimpin. Masyarakat dengan bertanggungjawab. Negara dengan kedaulatan terpelihara.', 'Aku belajar tiga peringkat sokongan kepada pemimpin. Diri menghormati pemimpin negara, masyarakat menjadi bertanggungjawab apabila menyokong pemimpin berwibawa, dan negara memastikan kedaulatan terpelihara.', 'Tepat! Tiga halaman kecil ditambah ke dalam album itu untuk diri, masyarakat dan negara.'),
(NULL, 'e7_n3_s8', 'hint', 'Nilai itu ialah bertanggungjawab dan hormat-menghormati.', NULL, NULL),
(725, NULL, 'hint', 'Satu nilai ialah bertanggungjawab. Satu lagi berkaitan menghormati pemimpin.', 'Album siap dengan dua nilai teras sivik. Bertanggungjawab terhadap negara dan hormat-menghormati pemimpin, supaya kedaulatan negara dan perpaduan rakyat kekal terpelihara.', 'Tahniah! Album kad koleksi Perdana Menteri siap dan Cikgu menyerahkannya kepada pustakawan sekolah.');
INSERT INTO DialogueLine (npcID, narrativeID, sceneID, dialogueLine, sequenceOrder) VALUES
(121, 701, NULL, 'Tugasku merakam siaran khas tentang Perdana Menteri. Jika tarikh atau nama salah, penonton akan menerima sejarah yang salah, {nama}.', 1),
(121, 701, NULL, 'Aku belajar bahawa pemimpin yang berjasa wajar dihormati dan pengorbanan mereka dijadikan iktibar.', 2),
(121, 701, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wartawan muda di Pejabat Perdana Menteri. Tanya dengan teliti dan catat dengan betul. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(121, 701, 'e7_n1_s1', 'Lima minit lagi siaran khas bermula, dan skrip aku dipenuhi cop kopi. Penerbit minta aku sebut Perdana Menteri dipilih terus oleh rakyat. Betulkah begitu?', 1),
(132, 701, 'e7_n1_s1', 'Jangan tergesa-gesa, wartawan muda. Perdana Menteri merupakan ketua kerajaan yang mengetuai pentadbiran negara.', 2),
(132, 701, 'e7_n1_s1', 'Beliau dilantik secara rasmi oleh beta, Yang di-Pertuan Agong, Ketua Utama Negara. Tetapi beliau mesti mendapat sokongan majoriti Ahli Dewan Rakyat.', 3),
(121, 701, 'e7_n1_s1', 'Dan jawatan itu dahulu tiada, Tuanku?', 4),
(132, 701, 'e7_n1_s1', 'Jawatan Perdana Menteri diwujudkan selepas Tanah Melayu merdeka pada 31 Ogos 1957, dan kekal hingga hari ini.', 5),
(NULL, 701, 'e7_n1_s1', 'Nota ini pun menyebutnya. Perdana Menteri ialah ketua kerajaan yang dilantik oleh Yang di-Pertuan Agong.', 6),
(121, 701, 'e7_n1_s1', 'Cepat, siaran bermula sebentar lagi! Jadi bagaimana aku patut menerangkan cara Perdana Menteri dilantik kepada penonton?', 7),
(121, 701, 'e7_n1_s2', 'Pita rakaman empat Perdana Menteri pertama bercampur-campur. Siapa dahulu, siapa kemudian?', 1),
(124, 701, 'e7_n1_s2', 'Beta dahulu. Tunku Abdul Rahman menjadi Perdana Menteri pertama pada 31 Ogos 1957.', 2),
(125, 701, 'e7_n1_s2', 'Aku Tun Abdul Razak. Aku menjadi Perdana Menteri kedua pada 22 September 1970.', 3),
(126, 701, 'e7_n1_s2', 'Dan aku Tun Hussein Onn, Perdana Menteri ketiga pada 15 Januari 1976.', 4),
(127, 701, 'e7_n1_s2', 'Aku pula Tun Dr. Mahathir, yang keempat pada 16 Julai 1981.', 5),
(122, 701, 'e7_n1_s2', 'Kalau pita ini terbalik, penonton akan belajar sejarah yang songsang.', 6),
(NULL, 701, 'e7_n1_s2', 'Aku akan susun pita itu mengikut tarikh mereka mula berkhidmat.', 7),
(122, 701, 'e7_n1_s2', 'Ingat, tarikhnya mesti betul. Tetapi kenapa kita perlu menyusun pemimpin mengikut tarikh?', 8),
(121, 701, 'e7_n1_s3', 'Rakaman laungan kemerdekaan ini kabur. Mana buktinya kemerdekaan dicapai melalui rundingan?', 1),
(124, 701, 'e7_n1_s3', 'Beta berdiri di podium Stadium Merdeka pada 31 Ogos 1957. Beta memperjuangkan kemerdekaan secara rundingan.', 2),
(124, 701, 'e7_n1_s3', 'Lihat papan Perisytiharan Kemerdekaan Malaya di podium itu, dan poster Merdeka! Malaya! yang dipegang rakyat.', 3),
(124, 701, 'e7_n1_s3', 'Rakyat bersorak dan mengangkat tangan menyambut kemerdekaan, wartawan muda.', 4),
(NULL, 701, 'e7_n1_s3', 'Tunku di podium, papan perisytiharan, poster Merdeka! Malaya!, dan rakyat yang bersorak. Aku akan cari keempat-empatnya.', 5),
(124, 701, 'e7_n1_s3', 'Tunjukkan dengan tepat. Dan bagaimana kemerdekaan itu dicapai, wartawan muda?', 6),
(121, 701, 'e7_n1_s4', 'Tunku, boleh ceritakan latar hidup Tunku untuk siaran ini?', 1),
(124, 701, 'e7_n1_s4', 'Beta dilahirkan di Alor Setar, Kedah. Beta melanjutkan pelajaran di Universiti Cambridge dalam bidang undang-undang.', 2),
(124, 701, 'e7_n1_s4', 'Beta pernah berkhidmat sebagai Pegawai Daerah di Padang Terap, Langkawi dan Sungai Petani.', 3),
(124, 701, 'e7_n1_s4', 'Pada tahun 1955, beta menjadi Ketua Menteri Persekutuan Tanah Melayu. Rakyat memberi beta gelaran Bapa Kemerdekaan.', 4),
(122, 701, 'e7_n1_s4', 'Saya bimbang tarikh dan gelaran tersilap semasa siaran.', 5),
(NULL, 701, 'e7_n1_s4', 'Aku akan padankan biodata Tunku dengan maklumat yang betul.', 6),
(124, 701, 'e7_n1_s4', 'Baik. Tetapi mengapa biodata seseorang pemimpin mesti disampaikan dengan tepat?', 7),
(121, 701, 'e7_n1_s5', 'Skripku menulis Tun Razak menutup semua pejabat kerajaan selepas 13 Mei 1969. Betulkah begitu, Tun?', 1),
(125, 701, 'e7_n1_s5', 'Itu salah. Selepas peristiwa 13 Mei 1969, aku menubuhkan Majlis Gerakan Negara atau MAGERAN, untuk mengembalikan keamanan negara.', 2),
(125, 701, 'e7_n1_s5', 'Aku juga memperkenalkan Dasar Ekonomi Baru atau DEB, untuk membasmi kemiskinan rakyat dan menyusun semula masyarakat berbilang kaum.', 3),
(NULL, 701, 'e7_n1_s5', 'Nota pencapaian ini pun menyebut perkara yang sama. Tun Razak menubuhkan MAGERAN dan memperkenalkan DEB.', 4),
(125, 701, 'e7_n1_s5', 'Baca betul-betul, kerana ini sejarah. Jadi mengapa dua langkah itu penting kepada masyarakat berbilang kaum?', 5),
(121, 701, 'e7_n1_s6', 'Tun Razak, di manakah rumah kelahiran Tun?', 1),
(125, 701, 'e7_n1_s6', 'Tempat lahir aku di Pulau Keladi, Pekan, Pahang.', 2),
(122, 701, 'e7_n1_s6', 'Dan pelajaran Tun di mana?', 3),
(125, 701, 'e7_n1_s6', 'Aku belajar di Kolej Melayu Kuala Kangsar, kemudian menyambung pelajaran undang-undang di Lincoln''s Inn, London.', 4),
(125, 701, 'e7_n1_s6', 'Aku pernah berkhidmat sebagai Setiausaha Kerajaan Negeri Pahang dan Menteri Besar Pahang. Rakyat memberi aku gelaran Bapa Pembangunan.', 5),
(NULL, 701, 'e7_n1_s6', 'Aku akan padankan biodata Tun Razak dengan tepat.', 6),
(122, 701, 'e7_n1_s6', 'Teliti ya. Tetapi mengapa kita perlu mengetahui perjalanan hidup seseorang pemimpin?', 7),
(121, 701, 'e7_n1_s7', 'Tun Hussein, mengapa Tun digelar Bapa Perpaduan?', 1),
(126, 701, 'e7_n1_s7', 'Aku memperkenalkan Program Rukun Tetangga untuk menggalakkan perpaduan dalam kalangan rakyat berbilang kaum.', 2),
(126, 701, 'e7_n1_s7', 'Aku juga memperkenalkan Amanah Saham Nasional Berhad, supaya kaum bumiputera mudah memiliki saham dalam syarikat berhad.', 3),
(122, 701, 'e7_n1_s7', 'Saya keliru antara ASN dengan program perpaduan.', 4),
(126, 701, 'e7_n1_s7', 'Aku dilahirkan di Johor Bahru, Johor, dan menjadi Perdana Menteri dari 15 Januari 1976 hingga 16 Julai 1981.', 5),
(NULL, 701, 'e7_n1_s7', 'Aku akan padankan ASN, Rukun Tetangga, gelaran, tempoh jawatan dan tempat lahir.', 6),
(126, 701, 'e7_n1_s7', 'Baik. Tetapi apakah yang patut kita lakukan terhadap program yang menyatukan rakyat berbilang kaum?', 7),
(122, 701, 'e7_n1_s8', 'Siaran khas hampir tamat. Siapa Bapa Kemerdekaan? Siapa Bapa Pembangunan?', 1),
(124, 701, 'e7_n1_s8', 'Beta, Tunku Abdul Rahman, digelar Bapa Kemerdekaan.', 2),
(125, 701, 'e7_n1_s8', 'Aku digelar Bapa Pembangunan, dan Tun Hussein digelar Bapa Perpaduan.', 3),
(127, 701, 'e7_n1_s8', 'Aku digelar Bapa Pemodenan, Tun Dr. Mahathir Mohamad.', 4),
(128, 701, 'e7_n1_s8', 'Aku Tun Abdullah Ahmad Badawi, Bapa Pembangunan Modal Insan.', 5),
(NULL, 701, 'e7_n1_s8', 'Aku akan padankan gelaran dengan pemimpinnya.', 6),
(122, 701, 'e7_n1_s8', 'Ada dua yang hampir serupa, jadi teliti. Dan mengapa setiap pemimpin diberi gelaran yang berbeza?', 7),
(122, 702, NULL, 'Tugasku mengajar murid mengenali tugas Perdana Menteri. Jika aku tersilap, murid akan mempelajari fakta yang salah, {nama}.', 1),
(122, 702, NULL, 'Aku belajar bahawa kepemimpinan yang berwibawa memajukan ekonomi, menjamin keselamatan dan menyatukan rakyat.', 2),
(122, 702, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, guru Sejarah di bilik darjah. Dengar soalan murid dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(123, 702, 'e7_n2_s1', 'Cikgu, gambar dalam buku teks ini hidup! Tun Dr. Mahathir keluar dari muka surat, tetapi saya tak tahu gambar ini menunjukkan tugas Perdana Menteri yang mana.', 1),
(127, 702, 'e7_n2_s1', 'Aku sedang mengadakan mesyuarat dengan Ketua-ketua Setiausaha Kementerian. Perdana Menteri ialah ketua pentadbir utama yang merancang dan menyelaraskan semua dasar negara.', 2),
(125, 702, 'e7_n2_s1', 'Aku meninjau tanaman getah di Felda Lurah Bilut. Perdana Menteri memastikan semua dasar pembangunan dapat ditingkatkan demi kesejahteraan rakyat.', 3),
(126, 702, 'e7_n2_s1', 'Aku bertemu Presiden Anwar Sadat pada 1977. Perdana Menteri menjalin hubungan diplomatik dan persahabatan dengan negara luar.', 4),
(122, 702, 'e7_n2_s1', 'Dan gambar watikah ini? Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat, lalu Yang di-Pertuan Agong menandatangani watikahnya.', 5),
(NULL, 702, 'e7_n2_s1', 'Aku akan padankan setiap gambar dengan tugas Perdana Menteri.', 6),
(123, 702, 'e7_n2_s1', 'Baik, Cikgu. Tetapi apakah tujuan semua tugas Perdana Menteri ini?', 7),
(123, 702, 'e7_n2_s2', 'Cikgu, siapa yang melantik Jemaah Menteri?', 1),
(132, 702, 'e7_n2_s2', 'Perdana Menteri mencadangkan senarai Jemaah Menteri, dan beta, Yang di-Pertuan Agong, melantik mereka.', 2),
(122, 702, 'e7_n2_s2', 'Perdana Menteri juga menasihati Yang di-Pertuan Agong berkaitan pemerintahan negara, dan mengiringi baginda ke Mesyuarat Majlis Raja-Raja.', 3),
(123, 702, 'e7_n2_s2', 'Dan siapa yang mempengerusikan mesyuarat Jemaah Menteri?', 4),
(124, 702, 'e7_n2_s2', 'Perdana Menteri sendiri. Mesyuarat Jemaah Menteri yang pertama selepas merdeka dipengerusikan oleh beta, Tunku.', 5),
(NULL, 702, 'e7_n2_s2', 'Aku akan padankan setiap tugas dengan penjelasannya.', 6),
(123, 702, 'e7_n2_s2', 'Baik, Cikgu. Jadi sebenarnya siapa yang mencadangkan, dan siapa yang melantik Jemaah Menteri?', 7),
(123, 702, 'e7_n2_s3', 'Cikgu, Tun Dr. Mahathir seorang doktor perubatan, bukan?', 1),
(127, 702, 'e7_n2_s3', 'Betul. Aku dilahirkan di Seberang Perak, Alor Setar, Kedah, dan belajar perubatan di Singapura.', 2),
(127, 702, 'e7_n2_s3', 'Pada tahun 1957, aku membuka Klinik MAHA di Alor Setar. Klinik itu masih beroperasi hingga hari ini.', 3),
(127, 702, 'e7_n2_s3', 'Aku menjadi Perdana Menteri keempat dari 16 Julai 1981 hingga 30 Oktober 2003, dan gelaran aku ialah Bapa Pemodenan.', 4),
(NULL, 702, 'e7_n2_s3', 'Aku akan padankan biodata Tun Dr. Mahathir dengan maklumat yang betul.', 5),
(123, 702, 'e7_n2_s3', 'Baik. Tetapi apakah kebaikan jika pemimpin berpendidikan dan berpengalaman seperti Tun?', 6),
(123, 702, 'e7_n2_s4', 'Cikgu, apa bukti Wawasan 2020 itu nyata?', 1),
(127, 702, 'e7_n2_s4', 'Pandang gambar ini. Menara Berkembar Petronas di KLCC dibina pada zaman aku, bersama KLIA dan Putrajaya.', 2),
(127, 702, 'e7_n2_s4', 'Itu kilang moden HICOM, untuk industri berteknologi tinggi. Itu pula papan carta menaik Wawasan 2020 menuju kemajuan.', 3),
(127, 702, 'e7_n2_s4', 'Jambatan layang dan jalan raya pula menunjukkan pembangunan seperti KLIA dan Putrajaya.', 4),
(NULL, 702, 'e7_n2_s4', 'Menara Berkembar Petronas, kilang HICOM, papan carta Wawasan 2020, dan jambatan layang. Aku akan cari keempat-empatnya.', 5),
(123, 702, 'e7_n2_s4', 'Baik, Cikgu. Dan apakah sebenarnya tujuan Wawasan 2020 itu?', 6),
(123, 702, 'e7_n2_s5', 'Bukankah Tun Dr. Mahathir hanya sekali menjadi Perdana Menteri?', 1),
(127, 702, 'e7_n2_s5', 'Tidak. Aku menjadi Perdana Menteri kali kedua, iaitu yang ketujuh, dari 10 Mei 2018 hingga 24 Februari 2020.', 2),
(127, 702, 'e7_n2_s5', 'Aku pernah berkhidmat sebagai Pengerusi PETRONAS dan Penasihat PROTON, dan melawat Jepun, Thailand dan United Kingdom.', 3),
(123, 702, 'e7_n2_s5', 'Dan apa wawasan baharu Tun pada masa itu?', 4),
(127, 702, 'e7_n2_s5', 'Aku memperkenalkan Wawasan Kemakmuran Bersama 2030.', 5),
(NULL, 702, 'e7_n2_s5', 'Nota ini pun menyebutnya. Wawasan baharu itu ialah Wawasan Kemakmuran Bersama 2030.', 6),
(123, 702, 'e7_n2_s5', 'Faham. Jadi apakah matlamat wawasan baharu itu kepada rakyat?', 7),
(123, 702, 'e7_n2_s6', 'Cikgu, Tun Abdullah ini belajar apa dahulu?', 1),
(128, 702, 'e7_n2_s6', 'Aku belajar Pengajian Islam di Universiti Malaya. Aku dilahirkan di Kampung Perlis, Bayan Lepas, Pulau Pinang.', 2),
(128, 702, 'e7_n2_s6', 'Aku pernah berkhidmat sebagai Setiausaha Majlis Gerakan Negara atau MAGERAN.', 3),
(128, 702, 'e7_n2_s6', 'Aku menjadi Perdana Menteri kelima dari 31 Oktober 2003 hingga 3 April 2009. Aku digelar Bapa Pembangunan Modal Insan.', 4),
(NULL, 702, 'e7_n2_s6', 'Aku akan padankan biodata Tun Abdullah dengan maklumat yang betul.', 5),
(128, 702, 'e7_n2_s6', 'Baik. Tetapi tahukah kamu apa maksud modal insan itu?', 6),
(123, 702, 'e7_n2_s7', 'Koridor Wilayah Ekonomi dan Pelan Integriti Nasional sama ke, Cikgu?', 1),
(128, 702, 'e7_n2_s7', 'Tidak sama. Satu untuk ekonomi, satu untuk akhlak.', 2),
(128, 702, 'e7_n2_s7', 'Koridor Wilayah Ekonomi aku perkenalkan untuk memastikan pembangunan ekonomi seimbang dan kemasukan pelaburan yang besar.', 3),
(128, 702, 'e7_n2_s7', 'Pelan Integriti Nasional atau PIN pula aku perkenalkan untuk membina masyarakat yang bermoral dan beretika.', 4),
(NULL, 702, 'e7_n2_s7', 'Nota ini pun menyebutnya. Pelan Integriti Nasional membina masyarakat yang bermoral dan beretika.', 5),
(128, 702, 'e7_n2_s7', 'Baca nota ini dan tentukan fungsi setiap satu. Jadi, mengapa pembangunan tidak cukup dengan ekonomi sahaja?', 6),
(123, 702, 'e7_n2_s8', 'Cikgu, apa moto 1Malaysia?', 1),
(129, 702, 'e7_n2_s8', 'Rakyat Didahulukan, Pencapaian Diutamakan. Aku memperkenalkan Gagasan 1Malaysia pada 3 April 2009.', 2),
(129, 702, 'e7_n2_s8', 'Gagasan ini bertujuan memperkukuh hubungan dan kerjasama antara kaum demi kesejahteraan negara.', 3),
(129, 702, 'e7_n2_s8', 'Aku dilahirkan di Kuala Lipis, Pahang, dan belajar ekonomi industri di Universiti Nottingham. Aku menjadi Perdana Menteri keenam dari 3 April 2009 hingga 9 Mei 2018.', 4),
(129, 702, 'e7_n2_s8', 'Aku juga melancarkan Program Transformasi Kerajaan atau GTP, untuk menjadikan negara berpendapatan tinggi selaras dengan Wawasan 2020.', 5),
(NULL, 702, 'e7_n2_s8', 'Aku akan padankan biodata dan pencapaian Dato'' Sri Najib.', 6),
(129, 702, 'e7_n2_s8', 'Baik. Jadi, apakah yang ditekankan oleh Gagasan 1Malaysia kepada rakyat?', 7),
(123, 702, 'e7_n2_s9', 'Cikgu, apa sumbangan Tan Sri Muhyiddin kepada rakyat?', 1),
(130, 702, 'e7_n2_s9', 'Aku dilahirkan di Muar, Johor, dan menjadi Perdana Menteri dari 1 Mac 2020 hingga 16 Ogos 2021.', 2),
(130, 702, 'e7_n2_s9', 'Aku menubuhkan Majlis Tindakan Ekonomi atau MTE, untuk menggalakkan pertumbuhan sosioekonomi dan meningkatkan pelaburan. Semasa PKP, aku juga mengumumkan bantuan untuk rakyat.', 3),
(131, 702, 'e7_n2_s9', 'Aku Dato'' Seri Ismail Sabri. Aku dilahirkan di Temerloh, Pahang, dan menjadi Perdana Menteri mulai 20 Ogos 2021.', 4),
(131, 702, 'e7_n2_s9', 'Aku memperkenalkan konsep Keluarga Malaysia, yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 5),
(NULL, 702, 'e7_n2_s9', 'Aku akan padankan sumbangan kedua-dua pemimpin itu.', 6),
(123, 702, 'e7_n2_s9', 'Baik, Cikgu. Jadi apakah yang boleh kita pelajari daripada pemimpin yang prihatin kepada rakyat?', 7),
(123, 703, NULL, 'Tugasku melengkapkan album kad koleksi dengan betul. Jika silap, projek sekolah akan menyalahkan jasa pemimpin, {nama}.', 1),
(123, 703, NULL, 'Aku belajar bahawa menghormati pemimpin dan menyokong kepimpinan negara memastikan kedaulatan dan perpaduan rakyat kekal terpelihara.', 2),
(123, 703, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid penyelidik dengan album kad koleksi. Semak setiap halaman dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(122, 703, 'e7_n3_s1', 'Pada zaman Kesultanan Melayu Melaka, siapakah ketua pembesar kerajaan?', 1),
(123, 703, 'e7_n3_s1', 'Kalau tidak silap saya, Perdana Menteri.', 2),
(122, 703, 'e7_n3_s1', 'Tidak. Nota ini menyebut bahawa Bendahara ialah Ketua Pembesar kerajaan pada zaman Kesultanan Melayu Melaka.', 3),
(122, 703, 'e7_n3_s1', 'Pada masa ini, pentadbiran kerajaan diketuai oleh Perdana Menteri. Jawatan itu diwujudkan selepas Tanah Melayu merdeka pada 31 Ogos 1957 dan kekal hingga hari ini.', 4),
(NULL, 703, 'e7_n3_s1', 'Dahulu Bendahara mengetuai pembesar, kini Perdana Menteri mengetuai pentadbiran. Aku akan tulis begitu dalam album.', 5),
(122, 703, 'e7_n3_s1', 'Teliti, jangan campur dua zaman. Jadi apakah persamaan antara kedua-dua jawatan itu?', 6),
(123, 703, 'e7_n3_s2', 'Saya sudah ada empat Perdana Menteri pertama dalam album. Lima lagi bagaimana, Cikgu?', 1),
(122, 703, 'e7_n3_s2', 'Susun mengikut tarikh mereka mula berkhidmat. Tun Abdullah Ahmad Badawi menjadi yang kelima pada 31 Oktober 2003.', 2),
(122, 703, 'e7_n3_s2', 'Dato'' Sri Najib yang keenam pada 3 April 2009. Tun Dr. Mahathir yang ketujuh, kali kedua, pada 10 Mei 2018.', 3),
(122, 703, 'e7_n3_s2', 'Muhyiddin yang kelapan pada 1 Mac 2020, dan Dato'' Seri Ismail Sabri yang kesembilan pada 20 Ogos 2021.', 4),
(NULL, 703, 'e7_n3_s2', 'Aku akan padankan semuanya. Kalau tersilap, album ini tidak boleh dihantar.', 5),
(122, 703, 'e7_n3_s2', 'Betul. Jadi sejak 1957 hingga 2021, berapa orangkah Perdana Menteri negara kita?', 6),
(123, 703, 'e7_n3_s3', 'Cikgu, mengapa pembentukan Malaysia dikira pencapaian Tunku?', 1),
(124, 703, 'e7_n3_s3', 'Beta berjaya merealisasikan pembentukan Malaysia pada 16 September 1963.', 2),
(122, 703, 'e7_n3_s3', 'Dan Tunku memperjuangkan kemerdekaan negara melalui apa?', 3),
(124, 703, 'e7_n3_s3', 'Melalui rundingan. Beta memperjuangkan kemerdekaan secara rundingan, bukan peperangan.', 4),
(NULL, 703, 'e7_n3_s3', 'Nota ini pun menyebut dua pencapaian itu. Memperjuangkan kemerdekaan secara rundingan dan merealisasikan pembentukan Malaysia.', 5),
(124, 703, 'e7_n3_s3', 'Betul. Jadi apakah yang dibawa oleh pemimpin yang berunding kepada negara?', 6),
(122, 703, 'e7_n3_s4', 'Pemimpin mana yang memperkenalkan Dasar Ekonomi Baru?', 1),
(123, 703, 'e7_n3_s4', 'Saya ingat, tetapi tidak pasti.', 2),
(125, 703, 'e7_n3_s4', 'Aku, Tun Abdul Razak, memperkenalkan Dasar Ekonomi Baru. Tunku pula memperjuangkan kemerdekaan secara rundingan.', 3),
(126, 703, 'e7_n3_s4', 'Aku, Tun Hussein, memperkenalkan Amanah Saham Nasional Berhad.', 4),
(127, 703, 'e7_n3_s4', 'Aku merealisasikan Wawasan 2020 melalui Putrajaya, KLIA dan KLCC. Tun Abdullah memperkenalkan Pelan Integriti Nasional.', 5),
(129, 703, 'e7_n3_s4', 'Aku pula melancarkan Program Transformasi Kerajaan atau GTP.', 6),
(NULL, 703, 'e7_n3_s4', 'Aku akan padankan semua enam pemimpin dengan pencapaian utama mereka.', 7),
(122, 703, 'e7_n3_s4', 'Jangan campur, ini peperiksaan kecil. Jadi apakah faedah pencapaian itu kepada rakyat?', 8),
(122, 703, 'e7_n3_s5', 'Mengapa kita perlu pemimpin yang memiliki ciri-ciri kepimpinan berwibawa?', 1),
(123, 703, 'e7_n3_s5', 'Supaya negara hebat, tetapi itu sahaja?', 2),
(122, 703, 'e7_n3_s5', 'Kad ini menjelaskannya. Pemimpin yang berwibawa memajukan sistem ekonomi negara, menjamin keselamatan negara dan membentuk kerajaan yang tersusun.', 3),
(122, 703, 'e7_n3_s5', 'Mereka juga menimbulkan rasa hormat antara pemimpin, mewujudkan negara yang membangun dan memudahkan pelaksanaan dasar-dasar pembangunan negara.', 4),
(NULL, 703, 'e7_n3_s5', 'Memajukan ekonomi, menjamin keselamatan dan membentuk kerajaan tersusun. Aku akan baca kad itu sekali lagi sebelum menjawab.', 5),
(122, 703, 'e7_n3_s5', 'Fikir tentang negara dan rakyat. Jadi apakah yang kita dapat apabila pemimpinnya berwibawa?', 6),
(122, 703, 'e7_n3_s6', 'Bagaimana kita menghargai Perdana Menteri? Bukan dengan kata-kata kosong sahaja.', 1),
(123, 703, 'e7_n3_s6', 'Kad ini menyebut empat cara, Cikgu.', 2),
(122, 703, 'e7_n3_s6', 'Kita boleh mengeratkan perpaduan antara kaum dan mengekalkan taat setia terhadap pemimpin.', 3),
(122, 703, 'e7_n3_s6', 'Kita juga boleh menjaga nama baik negara dan menjaga keamanan negara.', 4),
(NULL, 703, 'e7_n3_s6', 'Aku akan baca kad dan pilih yang betul. Mengeratkan perpaduan antara kaum dan menjaga nama baik negara.', 5),
(122, 703, 'e7_n3_s6', 'Satu kad pun jangan tersilap. Jadi bagaimana kita menghormati pemimpin dalam kehidupan seharian?', 6),
(122, 703, 'e7_n3_s7', 'Mengapa kita perlu menyokong kepimpinan negara? Fikir tiga peringkat, iaitu diri, masyarakat dan negara.', 1),
(123, 703, 'e7_n3_s7', 'Bagi diri, kita perlu menghormati pemimpin negara.', 2),
(122, 703, 'e7_n3_s7', 'Bagi masyarakat, sokongan kepada pemimpin berwibawa melahirkan masyarakat yang bertanggungjawab.', 3),
(122, 703, 'e7_n3_s7', 'Dan bagi negara, sikap bertanggungjawab memastikan kedaulatan negara terpelihara.', 4),
(NULL, 703, 'e7_n3_s7', 'Aku akan padankan setiap peringkat dengan faedahnya.', 5),
(122, 703, 'e7_n3_s7', 'Jangan campur aduk. Jadi apakah yang terjamin apabila kita menyokong kepimpinan negara?', 6),
(122, 703, 'e7_n3_s8', 'Unit ini mengajar dua nilai teras sivik. Apakah nilai itu?', 1),
(123, 703, 'e7_n3_s8', 'Satu saya tahu, bertanggungjawab. Satu lagi?', 2),
(122, 703, 'e7_n3_s8', 'Nota ini menyebut bahawa kita menghargai jasa pemimpin yang memajukan negara.', 3),
(122, 703, 'e7_n3_s8', 'Kita perlu menghormati pemimpin dan bersikap bertanggungjawab terhadap negara, supaya kedaulatan negara dan perpaduan rakyat kekal terpelihara.', 4),
(NULL, 703, 'e7_n3_s8', 'Aku akan baca nota dan pilih jawapan yang betul. Bertanggungjawab dan hormat-menghormati.', 5),
(122, 703, 'e7_n3_s8', 'Teliti, nilai itu berkaitan dengan hubungan kita dengan pemimpin. Jadi bagaimana kita akan mengamalkannya selepas album ini siap?', 6);
INSERT INTO QuestionBank (bankID, eraID) VALUES (7, 7)
INSERT INTO Question (questionID, bankID, questionText, option_a, option_b, option_c, option_d, correctAnswer, hint, explanation) VALUES
(701, 7, 'Siapakah yang melantik Perdana Menteri secara rasmi?', 'Menteri Besar', 'Ketua Hakim Negara', 'Yang di-Pertuan Agong', 'Speaker Dewan Rakyat', 'C', 'Ketua Utama Negara.', 'Perdana Menteri dilantik secara rasmi oleh Yang di-Pertuan Agong.'),
(702, 7, 'Perdana Menteri perlu mendapat sokongan majoriti...', 'Ahli Dewan Negara', 'Ahli Dewan Rakyat', 'Hakim Mahkamah', 'Sultan negeri', 'B', 'Dewan yang dipilih rakyat.', 'Perdana Menteri perlu mendapat sokongan majoriti Ahli Dewan Rakyat.'),
(703, 7, 'Jawatan Perdana Menteri diwujudkan selepas...', 'Tanah Melayu merdeka pada 31 Ogos 1957', 'Pembentukan Malaysia pada 1963', 'Peristiwa 13 Mei 1969', 'Kejatuhan Melaka pada 1511', 'A', 'Tarikh kemerdekaan.', 'Jawatan Perdana Menteri diwujudkan selepas kemerdekaan pada 31 Ogos 1957.'),
(704, 7, 'Pada zaman Kesultanan Melayu Melaka, ketua pembesar kerajaan ialah...', 'Laksamana', 'Temenggung', 'Syahbandar', 'Bendahara', 'D', 'Kini jawatan itu diganti oleh Perdana Menteri.', 'Bendahara ialah Ketua Pembesar kerajaan pada zaman Kesultanan Melayu Melaka.'),
(705, 7, 'Berapakah orang Perdana Menteri Malaysia dari tahun 1957 hingga 2021?', 'Tujuh', 'Lapan', 'Sembilan', 'Sepuluh', 'C', 'Termasuk Tun Dr. Mahathir dua kali.', 'Sejak 1957 hingga 2021, negara kita mempunyai sembilan orang Perdana Menteri.'),
(706, 7, 'Siapakah Perdana Menteri pertama Malaysia?', 'Tun Abdul Razak', 'Tunku Abdul Rahman', 'Tun Hussein Onn', 'Tun Dr. Mahathir', 'B', 'Digelar Bapa Kemerdekaan.', 'Tunku Abdul Rahman ialah Perdana Menteri pertama.'),
(707, 7, 'Tunku Abdul Rahman digelar...', 'Bapa Kemerdekaan', 'Bapa Pembangunan', 'Bapa Perpaduan', 'Bapa Pemodenan', 'A', 'Beliau memperjuangkan kemerdekaan.', 'Tunku digelar Bapa Kemerdekaan.'),
(708, 7, 'Tunku Abdul Rahman dilahirkan di...', 'Pekan, Pahang', 'Johor Bahru, Johor', 'Bayan Lepas, Pulau Pinang', 'Alor Setar, Kedah', 'D', 'Rumah Merdeka terletak di sana.', 'Tunku dilahirkan pada 8 Februari 1903 di Alor Setar, Kedah.'),
(709, 7, 'Tunku Abdul Rahman melanjutkan pelajaran undang-undang di...', 'Lincoln''s Inn', 'Raffles College', 'Universiti Cambridge', 'Universiti Nottingham', 'C', 'Di England.', 'Tunku melanjutkan pelajaran di Universiti Cambridge dalam bidang undang-undang.'),
(710, 7, 'Tunku Abdul Rahman berjaya merealisasikan pembentukan Malaysia pada...', '31 Ogos 1957', '16 September 1963', '13 Mei 1969', '1 April 1946', 'B', 'Hari Malaysia.', 'Tunku merealisasikan pembentukan Malaysia pada 16 September 1963.'),
(711, 7, 'Siapakah Perdana Menteri kedua Malaysia?', 'Tun Abdul Razak', 'Tun Hussein Onn', 'Tun Abdullah', 'Tan Sri Muhyiddin', 'A', 'Menggantikan Tunku pada 22 September 1970.', 'Tun Abdul Razak ialah Perdana Menteri kedua.'),
(712, 7, 'Tun Abdul Razak digelar...', 'Bapa Kemerdekaan', 'Bapa Perpaduan', 'Bapa Pemodenan', 'Bapa Pembangunan', 'D', 'Beliau memperkenalkan DEB.', 'Tun Razak digelar Bapa Pembangunan.'),
(713, 7, 'Tun Abdul Razak mengembalikan keamanan selepas peristiwa 13 Mei 1969 melalui...', 'Pelan Integriti Nasional', 'Majlis Tindakan Ekonomi', 'Majlis Gerakan Negara (MAGERAN)', 'Amanah Saham Nasional', 'C', 'Pentadbiran MAGERAN.', 'Tun Razak mengembalikan keamanan melalui pentadbiran Majlis Gerakan Negara (MAGERAN).'),
(714, 7, 'Dasar yang diperkenalkan untuk membasmi kemiskinan dan menyusun semula masyarakat ialah...', 'Wawasan 2020', 'Dasar Ekonomi Baru (DEB)', 'Gagasan 1Malaysia', 'Keluarga Malaysia', 'B', 'Zaman Tun Razak.', 'DEB diperkenalkan oleh Tun Razak untuk membasmi kemiskinan dan menyusun semula masyarakat.'),
(715, 7, 'Tun Abdul Razak dilahirkan di...', 'Pulau Keladi, Pekan, Pahang', 'Kuala Lipis, Pahang', 'Temerloh, Pahang', 'Bayan Lepas, Pulau Pinang', 'A', 'Replika rumahnya ada di sana.', 'Tun Razak dilahirkan di Pulau Keladi, Pekan, Pahang.'),
(716, 7, 'Siapakah Perdana Menteri ketiga Malaysia?', 'Tun Abdul Razak', 'Tun Dr. Mahathir', 'Tun Abdullah', 'Tun Hussein Onn', 'D', 'Digelar Bapa Perpaduan.', 'Tun Hussein Onn ialah Perdana Menteri ketiga.'),
(717, 7, 'Tun Hussein Onn digelar...', 'Bapa Pemodenan', 'Bapa Pembangunan', 'Bapa Perpaduan', 'Bapa Kemerdekaan', 'C', 'Rukun Tetangga.', 'Tun Hussein Onn digelar Bapa Perpaduan.'),
(718, 7, 'Program yang diperkenalkan Tun Hussein Onn untuk menggalakkan perpaduan ialah...', 'Program Transformasi Kerajaan', 'Program Rukun Tetangga', 'Pelan Integriti Nasional', 'Wawasan 2020', 'B', 'Nama yang mengandungi jiran.', 'Tun Hussein memperkenalkan Program Rukun Tetangga untuk menggalakkan perpaduan.'),
(719, 7, 'Amanah Saham Nasional Berhad diperkenalkan oleh...', 'Tun Hussein Onn', 'Tun Abdullah', 'Dato'' Sri Najib', 'Tunku Abdul Rahman', 'A', 'Memudahkan bumiputera memiliki saham.', 'ASNB diperkenalkan Tun Hussein Onn.'),
(720, 7, 'Siapakah Perdana Menteri keempat dan ketujuh Malaysia?', 'Tun Abdullah Ahmad Badawi', 'Tan Sri Muhyiddin', 'Dato'' Sri Najib', 'Tun Dr. Mahathir Mohamad', 'D', 'Pernah dua kali menjadi Perdana Menteri.', 'Tun Dr. Mahathir ialah Perdana Menteri keempat dan ketujuh.'),
(721, 7, 'Tun Dr. Mahathir digelar...', 'Bapa Perpaduan', 'Bapa Kemerdekaan', 'Bapa Pemodenan', 'Bapa Pembangunan Modal Insan', 'C', 'Wawasan 2020.', 'Tun Dr. Mahathir digelar Bapa Pemodenan.'),
(722, 7, 'Wawasan 2020 direalisasikan melalui pembinaan...', 'Rumah Merdeka dan Padang Kelab', 'Putrajaya, KLIA dan Menara Berkembar Petronas', 'Galeria Perdana dan Stadium Merdeka', 'Felda Lurah Bilut dan Gurdwara', 'B', 'Banyak dibina pada zaman beliau.', 'Wawasan 2020 direalisasikan melalui Pusat Pentadbiran Putrajaya, KLIA dan Menara Berkembar Petronas.'),
(723, 7, 'Wawasan yang diperkenalkan oleh Tun Dr. Mahathir pada kali kedua ialah...', 'Wawasan Kemakmuran Bersama 2030', 'Wawasan 2020', 'Gagasan 1Malaysia', 'Keluarga Malaysia', 'A', 'Menjelang 2030.', 'Pada kali kedua, Tun Dr. Mahathir memperkenalkan Wawasan Kemakmuran Bersama 2030.'),
(724, 7, 'Siapakah Perdana Menteri kelima Malaysia?', 'Dato'' Sri Najib', 'Tun Dr. Mahathir', 'Tan Sri Muhyiddin', 'Tun Abdullah Ahmad Badawi', 'D', 'Menjadi Perdana Menteri pada 31 Oktober 2003.', 'Tun Abdullah Ahmad Badawi ialah Perdana Menteri kelima.'),
(725, 7, 'Tun Abdullah Ahmad Badawi digelar...', 'Bapa Pemodenan', 'Bapa Kemerdekaan', 'Bapa Pembangunan Modal Insan', 'Bapa Perpaduan', 'C', 'Memberi tumpuan kepada rakyat.', 'Tun Abdullah digelar Bapa Pembangunan Modal Insan.'),
(726, 7, 'Pelan yang diperkenalkan untuk membina masyarakat bermoral dan beretika ialah...', 'Dasar Ekonomi Baru', 'Pelan Integriti Nasional (PIN)', 'Majlis Tindakan Ekonomi', 'Program Transformasi Kerajaan', 'B', 'Diperkenalkan oleh Tun Abdullah.', 'PIN diperkenalkan untuk membina masyarakat yang bermoral dan beretika.'),
(727, 7, 'Gagasan 1Malaysia diperkenalkan oleh...', 'Dato'' Sri Mohd Najib', 'Tun Dr. Mahathir', 'Tun Hussein Onn', 'Tan Sri Muhyiddin', 'A', 'Moto: Rakyat Didahulukan, Pencapaian Diutamakan.', 'Gagasan 1Malaysia diperkenalkan oleh Dato'' Sri Najib pada 3 April 2009.'),
(728, 7, 'Majlis Tindakan Ekonomi (MTE) ditubuhkan oleh...', 'Dato'' Seri Ismail Sabri', 'Tun Abdullah', 'Tun Hussein Onn', 'Tan Sri Muhyiddin Md Yassin', 'D', 'Semasa pandemik COVID-19.', 'MTE ditubuhkan oleh Tan Sri Muhyiddin untuk menggalakkan pertumbuhan sosioekonomi dan pelaburan.'),
(729, 7, 'Konsep Keluarga Malaysia diperkenalkan oleh...', 'Dato'' Sri Najib', 'Tun Abdullah', 'Dato'' Seri Ismail Sabri Yaakob', 'Tan Sri Muhyiddin', 'C', 'Meraikan keterangkuman.', 'Konsep Keluarga Malaysia diperkenalkan Dato'' Seri Ismail Sabri.'),
(730, 7, 'Manakah yang BUKAN tugas Perdana Menteri?', 'Menasihati Yang di-Pertuan Agong', 'Menggubal undang-undang sendiri tanpa Parlimen', 'Mengetuai Jemaah Menteri', 'Menjalin hubungan diplomatik', 'B', 'Semak keempat-empat tugas.', 'Tugas PM termasuk menasihati Agong, mengetuai Jemaah Menteri dan menjalin hubungan diplomatik.'),
(731, 7, 'Apakah kepentingan pemimpin yang memiliki ciri kepimpinan berwibawa?', 'Menjamin keselamatan negara dan memajukan ekonomi', 'Menyukarkan pelaksanaan dasar', 'Memecahkan perpaduan rakyat', 'Melemahkan ekonomi negara', 'A', 'Fikirkan negara.', 'Pemimpin berwibawa menjamin keselamatan, memajukan ekonomi dan membentuk kerajaan tersusun.'),
(732, 7, 'Manakah cara menunjukkan penghargaan kepada Perdana Menteri?', 'Menyebarkan fitnah tentang pemimpin', 'Mencemarkan nama baik negara', 'Mengabaikan keamanan negara', 'Mengeratkan perpaduan antara kaum', 'D', 'Hormat dan setia.', 'Kita menghargai pemimpin dengan mengeratkan perpaduan, taat setia, menjaga nama baik dan keamanan negara.'),
(733, 7, 'Apakah kepentingan memberikan sokongan kepada kepimpinan negara?', 'Menambah pertelingkahan politik', 'Menggagalkan pembangunan', 'Menjamin keamanan dan keharmonian negara', 'Menghalang kestabilan ekonomi', 'C', 'Kestabilan politik juga.', 'Sokongan kepada kepimpinan negara menjamin keamanan, keharmonian, kestabilan politik dan kemajuan ekonomi.'),
(734, 7, 'Apakah nilai teras sivik dalam Unit Pemimpin Negara?', 'Bersaing dan berebut kuasa', 'Bertanggungjawab dan hormat-menghormati', 'Mementingkan diri dan berdendam', 'Mengabaikan peraturan', 'B', 'Dua nilai.', 'Nilai teras sivik unit ini ialah bertanggungjawab dan hormat-menghormati.'),
(735, 7, 'Kemerdekaan dicapai melalui rundingan, bukan peperangan. Apakah kesan baik cara ini kepada negara?', 'Negara merdeka secara aman dan rakyat dapat bersatu membina masa depan', 'Negara merdeka tetapi rakyat berpecah dan tidak mahu bekerjasama lagi selepas itu', 'Negara merdeka kerana kuasa asing sendiri yang mahu pergi sahaja', 'Negara merdeka tetapi tidak perlu lagi dipertahankan oleh rakyatnya', 'A', 'Ingat perjuangan Tunku di Stadium Merdeka.', 'Perjuangan secara rundingan membawa kemerdekaan secara aman, lalu rakyat bersatu membina negara.'),
(736, 7, 'Skrip siaran menyebut Perdana Menteri dipilih terus oleh rakyat. Bagaimanakah wartawan patut membetulkannya?', 'Dilantik oleh Yang di-Pertuan Agong tanpa memerlukan sokongan sesiapa pun di Parlimen', 'Dilantik oleh Jemaah Menteri selepas mesyuarat mereka yang pertama', 'Dipilih oleh Ketua-ketua Setiausaha Kementerian dalam mesyuarat khas', 'Dilantik oleh Yang di-Pertuan Agong dengan sokongan majoriti Dewan Rakyat', 'D', 'Ingat siapa yang melantik dan siapa yang memberi sokongan.', 'Perdana Menteri dilantik secara rasmi oleh Yang di-Pertuan Agong dan perlu mendapat sokongan majoriti Ahli Dewan Rakyat.'),
(737, 7, 'Mengapakah Dasar Ekonomi Baru diperkenalkan selepas peristiwa 13 Mei 1969?', 'Untuk menutup semua pejabat kerajaan sehingga keadaan menjadi tenang semula', 'Untuk menghentikan perdagangan antara negeri selama bertahun-tahun', 'Untuk membasmi kemiskinan dan menyusun semula masyarakat berbilang kaum', 'Untuk memisahkan petempatan setiap kaum mengikut kegiatan ekonomi', 'C', 'Fikirkan jurang antara kaum.', 'DEB bertujuan membasmi kemiskinan rakyat dan menyusun semula masyarakat berbilang kaum selepas keamanan dipulihkan melalui MAGERAN.'),
(738, 7, 'Taman perumahan anda mahu menggalakkan perpaduan antara jiran berbilang kaum. Program Perdana Menteri manakah yang paling sesuai dijadikan contoh?', 'Amanah Saham Nasional Berhad yang diperkenalkan oleh Tun Hussein', 'Program Rukun Tetangga yang diperkenalkan oleh Tun Hussein Onn', 'Koridor Wilayah Ekonomi yang diperkenalkan oleh Tun Abdullah', 'Program Transformasi Kerajaan yang dilancarkan oleh Dato'' Sri Najib', 'B', 'Fikirkan perpaduan antara jiran.', 'Program Rukun Tetangga menggalakkan perpaduan dalam kalangan rakyat berbilang kaum, termasuk jiran.'),
(739, 7, 'Mengapakah Tun Dr. Mahathir memperkenalkan Wawasan Kemakmuran Bersama 2030 semasa menjadi Perdana Menteri kali kedua?', 'Supaya kemakmuran negara dapat dinikmati oleh semua rakyat bersama-sama', 'Supaya kemakmuran negara hanya dinikmati oleh sebahagian kecil kaum sahaja kelak', 'Supaya Wawasan 2020 dibatalkan dan dilupakan oleh semua rakyat', 'Supaya pelaburan negara dihentikan sehingga tahun yang berikutnya', 'A', 'Perhatikan perkataan ''Bersama''.', 'Wawasan Kemakmuran Bersama 2030 bermatlamat memakmurkan semua rakyat secara bersama-sama.'),
(740, 7, 'Pembangunan ekonomi yang pesat boleh menimbulkan masalah jika rakyat kurang berakhlak. Pelan manakah yang membantu menanganinya?', 'Koridor Wilayah Ekonomi untuk menarik kemasukan pelaburan yang besar', 'Program Transformasi Kerajaan untuk menjadikan negara berpendapatan tinggi', 'Majlis Tindakan Ekonomi untuk menggalakkan pertumbuhan sosioekonomi', 'Pelan Integriti Nasional untuk membina masyarakat bermoral dan beretika', 'D', 'Fikirkan moral dan etika.', 'Pelan Integriti Nasional diperkenalkan oleh Tun Abdullah untuk membina masyarakat yang bermoral dan beretika.'),
(741, 7, 'Moto Gagasan 1Malaysia ialah ''Rakyat Didahulukan, Pencapaian Diutamakan''. Apakah maksud ''Rakyat Didahulukan'' dalam pelaksanaan dasar?', 'Rakyat perlu menunggu giliran mereka selepas semua pemimpin selesai bertugas nanti', 'Hanya rakyat yang kaya dibenarkan menyertai program kerajaan', 'Kepentingan dan kesejahteraan rakyat diberi keutamaan dalam setiap dasar', 'Dasar kerajaan hanya dilaksanakan apabila pemimpin mahu sahaja', 'C', 'Fikirkan siapa yang dimanfaatkan.', 'Moto itu menekankan kepentingan dan kesejahteraan rakyat sebagai keutamaan dalam dasar kerajaan.'),
(742, 7, 'Konsep Keluarga Malaysia meraikan pelbagai agama, bangsa, kaum dan usia. Tindakan murid manakah yang sejajar dengan konsep itu?', 'Hanya berkawan dengan rakan yang sama agama dan sama bangsa', 'Berkawan dan membantu rakan daripada pelbagai agama, bangsa dan usia', 'Mengabaikan warga emas kerana usia mereka berbeza daripada kita', 'Memilih rakan sekelas mengikut kaum ketika membuat kerja kumpulan', 'B', 'Fikirkan keterangkuman.', 'Konsep Keluarga Malaysia meraikan keterangkuman, jadi murid patut berkawan dan membantu semua rakan tanpa mengira latar belakang.'),
(743, 7, 'Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat kepada Yang di-Pertuan Agong. Apakah tujuan tugas ini?', 'Mewakili negara untuk menjalin kerjasama dengan negara lain', 'Menggantikan semua anggota Jemaah Menteri dengan orang baharu setiap tahun', 'Menghentikan hubungan Malaysia dengan semua negara luar', 'Memilih Ketua-ketua Setiausaha bagi setiap kementerian negara', 'A', 'Ingat pertemuan Tun Hussein dengan Presiden Anwar Sadat.', 'Duta, diplomat dan konsulat mewakili negara untuk menjalin hubungan diplomatik dan kerjasama dengan negara luar.');
